          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"8a4ba327-158f-5ced-8e48-2b09f00369b2","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل -قتل عمد باستخدام سكني -إقرار املدعى عليه -طلب أولياء الدم القصاص -ثبوت إدانة -عدم وجود سوابق -سقوط القود لوجود ولد منها -صرف النظر عن القصاص وإفهام األولياء بأن لهم املطالبة بالدية -النظر يف بشاعة اجلرمية يكون سبب ا للحكم بالقتل تعزير ا.","document_number":"33463560","case_number":"33198415","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/23","year":"1434","subject":"قتل -قتل عمد باستخدام سكني -إقرار املدعى عليه -طلب أولياء الدم القصاص -ثبوت إدانة -عدم وجود سوابق -سقوط القود لوجود ولد منها -صرف النظر عن القصاص وإفهام األولياء بأن لهم املطالبة بالدية -النظر يف بشاعة اجلرمية يكون سبب ا للحكم بالقتل تعزير ا.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33463560 :‬تاريخه‪1433/11/23 :‬هـ‬\n                     ‫رقم الدعوى‪33198415:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 1/1/232‬تاريخه‪1434/11/12 :‬هـ‬\n\n\n ‫قتــل ‪ -‬قتــل عمــد باســتخدام ســكني ‪ -‬إقــرار املدعــى عليــه ‪ -‬طلــب أوليــاء‬\n ‫الــدم القصــاص ‪ -‬ثبــوت إدانــة ‪ -‬عــدم وجــود ســوابق ‪ -‬ســقوط القــود‬\n ‫لوجــود ولــد منهــا ‪ -‬صــرف النظــر عــن القصــاص وإفهــام األوليــاء بــأن‬\n ‫لهــم املطالبــة بالديــة ‪ -‬النظــر يف بشــاعة اجلرميــة يكــون ســبب ًا للحكــم‬\n                                                              ‫بالقتــل تعزيــر ًا‪.‬‬\n\n\n\n\n ‫‪ -1‬قول ابن قدامة يف املغني (ج‪ »:)486/11‬فصل‪ :‬لو قتل أحد األبوين‬\n ‫صاحبــه ولهمــا ولــد لــم يجــب القصــاص ألنــه لــو وجــب لوجــب لولــده‬\n ‫وال يجــب للولــد قصــاص علــى والــده ألنــه إذا لــم يجــب باجلنايــة عليــه‬\n ‫فــأن ال يجــب لــه باجلنايــة علــى غيــره أولــى وســواء كان الولــد ذكــر ًا‬\n ‫أو أنثــى أو كان للمقتــول ولــد ســواه أو مــن يشــاركه يف امليــراث أو لــم‬\n ‫يكــن ألنــه لــو ثبــت القصــاص لوجــب لــه جــزء منــه وال ميكــن وجوبــه‬\n ‫وإذا لــم يثبــت بعضــه ســقط كلــه ألنــه ال يتبعــض وصــار كمــا لــو‬\n ‫عفــا بعــض مســتحقي القصــاص عــن نصيبــه منــه « ونحــوه يف احلــاوي‬\n          ‫الكبيــر للمــارودي( ج ‪ ) 46/12‬ويف حاشــيتي قليــو بــي وعميــرة‬\n                                                            ‫( ج‪ 150/14‬ـ ‪.)151‬‬\n\n\n\n\n                                                                                     ‫‪108‬‬\n\f      ‫جــرى توجيــه االتهــام مــن اإلدعــاء العــام للمدعــى عليه بقتــل زوجته عمدا‬\n      ‫وعدوانــا بضربهــا بســاطور وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫مبــا قضــت بــه اإلرادة امللكيــة وتشــديد العقوبــة عليــه ولــو بقتلــه تعزيــرا‬\n      ‫لبشــاعة اجلرميــة حيــث تلقــت الشــرطة بالغــا مــن أحــد أقربــاء املجنــي‬\n      ‫عليهــا بــأن املدعــى عليــه اتصــل عليهــم وطلــب منهــم بــأن يأخذوهــا مــن‬\n      ‫بيتهــا فطرقــوا البــاب عــدة مــرات فلــم يجــب أحــد وبكســر البــاب عثــر‬\n      ‫عليهــا مقتولــة وعثــر باملوقــع علــى ســاطورا وســكينا ثــم قــام املدعــى‬\n      ‫عليــه بتســليم نفســه وأقــر لــدى احملقــق باجلرميــة وأن الدافــع لــه التخلــص‬\n      ‫مــن كثــرة اخلــاف بينهمــا ‪ ،‬انحصــر إرث املجنــي عليهــا يف والدهــا‬\n      ‫ووالدتهــا وأوالدهــا القصــر أحدهــم مــن املدعــى عليــه ‪ ،‬تــويف والدهــا‬\n      ‫وانحصــر إرثــه يف أوالده إخــوان املجنــي عليهــا وزوجتــه ‪ ،‬حضــر الورثــة‬\n      ‫عــدا البنــت وطالبــوا بالقصــاص ‪ ،‬أجــاب املدعــى عليــه بأنــه دخــل علــى‬\n      ‫زوجتــه وســمعها تتصــل بجــوال فأخفتــه فســألها عنــه فأنكــرت فقــام‬\n      ‫بتفتيــش املنــزل فلمــا وصــل إلــى املــكان الــذي أخفــت فيــه اجلــوال يف‬\n      ‫املطبــخ أخــذت زوجتــي ســكين ًا وأقبلــت عليــه وضربتــه يف يديــه اليمنــى‬\n      ‫فتنــاول ســاطورا وضربهــا بــه علــى رقبتهــا مــن اجلهــة اليمنــى ضربــة‬\n      ‫واحــدة فســقطت علــى األرض والــدم ينــزف مــن رقبتهــا وأنــه املتســبب‬\n      ‫الوحيــد يف وفاتهــا ولــم يشــاركه يف قتلهــا أحــد ولــم أكــن أقصــد قتلهــا‬\n      ‫ثــم أخــذ ابنتــه وذهــب بهــا ألختــه‪ ،‬جــرى االطــاع علــى إقــراره املصــدق‬\n      ‫شــرعا ومضمونــه بأنــه تخاصــم معهــا فتوجهــت نحــو املطبــخ وتناولــت‬\n      ‫ســكينا تريــد قتلــه فتنــاول فــورا ســاطورا وضربهــا بــه عــدة مــرات وال‬\n\n‫‪109‬‬\n\f‫يذكــر العــدد حتديــدا حتــى ماتــت وأن الدافــع لــه لذلــك رغبتــه يف‬\n‫التخلــص منهــا لكثــرة املشــاكل ‪ ،‬جــرى عــرض إقــراره فأنكــر أنــه‬\n‫ضربهــا عــدة مــرات وأن الصحيــح بأنــه ضربهــا ضربــة واحــدة ‪ ،‬جــرى‬\n‫االطــاع علــى تقريــر الطبــي الشــرعي املتضمــن إصابتهــا عــدة إصابــات‬\n‫بآلــة حــادة وأنهــا ســبب الوفــاة وبعرضــه علــى املدعــى عليــه أصــر بأنــه‬\n‫لــم يضربهــا إال ضربــة واحــدة ‪ ،‬جــرى االطــاع علــى إقــراره حتقيقــا‬\n‫والتقريــر الفنــي لتمثيــل اجلرميــة فظهــر بأنهمــا موافقــان ملــا جــاء يف الئحــة‬\n‫االدعــاء العــام ‪ ،‬وإلقــرار املدعــى عليــه يف مجلــس القضــاء بقتــل زوجتــه‬\n‫بضربهــا بســاطور حتــى وفاتهــا ‪ ،‬وملــا جــاء يف إقــراره املصــدق شــرعاً‪،‬‬\n‫وملــا جــاء يف التقريــر الطبــي الشــرعي‪ ،‬وملــا جــاء يف أوراق املعاملــة ‪،‬‬\n‫وإلقــرار املدعــي يف احلــق اخلــاص أصالــة ووكالــة أن للمدعــى عليــه بنتـ ًا‬\n‫مــن زوجتــه املجنــي عليهــا كمــا تضمنــه صــك حصــر الورثــة املشــار‬\n‫إليــه‪ ،‬وألن املــرأة ضعيفــة وبحاجــة إلــى مــن يحميهــا وألن املنــاط بالرجــل‬\n‫حمايــة زوجتــه ومــن حتــت يــده مــن النســاء‪ ،‬ولبشــاعة مــا أقــدم عليــه‬\n‫املدعــى عليــه مــن قتــل زوجتــه بهــذه الطريقــة وبحضــور ابنتهمــا الصغيــرة‬\n‫ومشــاهدتها ملــا حــدث وال يقــدم عليهــا إال مــن نزعــت مــن قلبــه الرحمــة‬\n‫‪ ،‬وهــي امرأتــه وحتــت فراشــه وال مغيــث لهــا غيــره وال تســتطيع أن‬\n‫تســتنجد بأحــد ‪ ،‬وليكــون عبــرة لغيــره مــن املعتديــن علــى محارمهــم‬\n‫الالتــي يأمــن علــى أرواحهــن مــن أزواجهــن‪ ،‬وجلميــع مــا ســبق‪ ،‬فقــد‬\n‫حكمنــا مبــا يلــي‪ :‬أوالً‪ /‬إدانــة املدعــى عليــه بقتــل زوجتــه عمــد ًا عدوانـ ًا‬\n‫وذلــك بضربهــا بســاطور عــدة ضربــات يف رقبتهــا ممــا أدى إلــى وفاتهــا‪.‬‬\n‫ثانيـاً‪ /‬صــرف النظــر عــن طلــب املدعــي يف احلــق اخلــاص أصالــة ووكالــة‬\n‫قتــل املدعــى عليــه قصاصـ ًا وإفهامــه بأن له وموكليــه املطالبة بنصيبهم‬\n\n\n                                                                                         ‫‪110‬‬\n\f      ‫يف ديــة مورثتهــم‪ .‬ثالث ـاً‪ /‬قتــل املدعــى عليــه تعزيــر ًا وذلــك بضــرب عنقــه‬\n      ‫بالســيف حتــى املــوت ‪ -‬قــرر املدعــي عليــه عــدم القناعــة باحلكــم وطلــب‬\n      ‫تقــدمي الئحــة اعتراضيــة فأجيــب لطلبــه وأفهــم بتعليمــات االســتئناف‬\n      ‫وقــرر املدعــي يف احلــق اخلــاص اعتراضــه وأفــاد أنــه علــى مطالبتــه بالقتــل‬\n      ‫قصاصـ ًا بــدون الئحــة اعتراضيــة ‪ -‬قــرر املدعــي العــام عــدم االعتــراض‬\n      ‫باحلكــم ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪ -‬صــدق احلكــم‬\n                                                              ‫مــن احملكمــة العليــا‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n      ‫وبعــد فلدينــا نحــن ‪...........‬و‪...........‬و ‪......................‬القضــاة باحملكمــة‬\n      ‫العامــة بنجــران بنــاء علــى املعاملــة الــواردة مــن محكمــة االســتئناف‬\n      ‫مبكــة املكرمــة برقــم وتاريــخ ‪1432/02/04‬ه ـ املتعلقــة بقضيــة مقتل‬\n      ‫‪...........‬مــن قبــل زوجهــا ‪......................‬واحملكــوم فيهــا بالقــرار الصــادر‬\n      ‫مــن هــذه احملكمــة برقــم وتاريــخ ‪1430/08/12‬ه ـ املتضمــن إثبــات‬\n      ‫إدانــة املدعــى عليــه بقتــل زوجتــه عمــد ًا عدوان ـ ًا وصــرف النظــر عــن‬\n      ‫الدعــوى اخلاصــة املطالبــة بقتلــه قصاص ـ ًا لوجــود بنــت لــه مــن زوجتــه‬\n      ‫املجنــي عليهــا واحلكــم بتعزيــره بالســجن ملــدة عشــرين عام ـ ًا واجللــد‬\n      ‫ألفــي جلــدة والصــادر بشــأنه مؤخــر ًا قــرار الدائــرة اجلزائيــة اخلماســية‬\n      ‫الثانيــة مبحكمــة االســتئناف مبكــة املكرمــة رقــم ‪ 1‬يف‬\n      ‫‪1432/01/27‬ه ـ املتضمــن نقــض احلكــم باألكثريــة وإحالــة القضيــة‬\n      ‫لقضــاة آخريــن حســب النظــام وعليــه أحيلــت القضيــة للمكتــب الســابع‬\n      ‫برقم يف ‪1433/03/20‬هـ والقيد رقم ‪ 33526077‬يف ‪1433/03/20‬هـ‬\n\n‫‪111‬‬\n\f‫وعليــه ففــي هــذا اليــوم األحــد ‪1433/10/29‬ه ـ افتتحــت اجللســة األولــى‬\n‫الســاعة الواحــدة والنصــف ظهــر ًا لدينــا نحــن ‪...........‬و‪...........‬و‪...........‬‬\n‫القضــاة باحملكمــة العامــة بنجــران وفيهــا حضــر املدعــي العــام‬\n‫‪ ......................‬مبوجــب خطــاب التكليــف رقــم ‪...........‬يف‬\n‫‪1433/08/20‬ه ـ وادعــى علــى احلاضــر معــه ‪...........‬ســعودي اجلنســية‬\n‫ا يف دعــواه إنــه بتاريــخ‬        ‫مبوجــب الســجل املدنــي رقــم ( ‪ )...........‬قائ ـ ً‬\n‫‪1426/07/28‬ه ـ يــوم اجلمعــة الســاعة الثالثــة والنصــف عصــر ًا تبلغــت‬\n‫غرفــة العمليــات بشــرطة منطقــة جنــران أنــه مت إبالغهم مــن قبل املواطن‬\n‫‪......................‬يفيــد بــأن املدعــى عليــه قــام باالتصــال عليهــم وأبلغهــم بأن‬\n‫يذهبــوا ألخــذ ابنتهــم ( زوجتــه ) مــن البيــت بحــي ‪...........‬وأنــه عنــد‬\n‫وصولــه للبيــت قــام بطــرق البــاب أكثــر مــن مــرة ولــم يفتــح أحــد ومت‬\n‫تســليم املوقــع لضابــط خفــر مركــز شــرطة ‪...........‬وباالنتقــال للموقــع‬\n‫مت كســر البــاب والدخــول إلــى املنــزل حيــث عثــر علــى زوجــة املدعــى‬\n‫عليــه املواطنــة ‪...........‬داخــل املطبــخ غارقــة يف دمائهــا وبهــا إصابــات‬\n‫قطعيــة مؤثــرة بالرقبــة مــن اجلهــة اليســرى واليمنــى وطعنــة غائــرة‬\n‫بكتفهــا األيســر وإصابــات قطعيــة متعــددة بباطــن وظاهــر كفهــا وقــد‬\n‫أثبــت التقريــر الطبــي رقــم ‪......................‬وتاريــخ ‪1426/08/13‬ه ـ أن‬\n‫الوفــاة بســبب النزيــف الدمــوي الغزيــر نتيجــة اإلصابــات القطعيــة‬\n‫العميقــة الســابقة الناشــئة عــن اإلصابــات بآلــة ذات نصــل حــاد وقــد‬\n‫وردنــا تقريــر فحــوص حيويــة رقــم (‪ )......................‬املتضمــن فحــص‬\n‫عينــة الدمــاء مــن مســرح اجلرميــة وثبــت أنهــا دمــاء آدميــة وإيجابيــة‬\n‫لالختبــار امليدانــي ( ‪ )- / +‬فصيلــة (‪ )O‬وقــد عثــر باملوقــع علــى ســاطور‬\n‫حــاد وســكني حــادة ومت نقــل اجلثمــان إلــى املستشــفى بعــد معاينــة املوقــع‬\n\n\n                                                                                            ‫‪112‬‬\n\f      ‫مــن الطبيــب الشــرعي وعضــو هيئــة التحقيــق واالدعــاء العــام بنجــران‬\n      ‫ويف متــام الســاعة السادســة والنصــف مــن مســاء اليــوم نفســه حضــر‬\n      ‫املدعــى عليــه برفقــة أحــد املواطنــن مبلغـ ًا ومســلم ًا نفســه بعــد أن اختبــأ‬\n      ‫بداخــل عمــارة قيــد اإلنشــاء بحــي ‪...........‬وباســتجواب املدعــى عليــه أقــر‬\n      ‫بقيامــه بقتــل زوجتــه املواطنــة ‪......................‬بضربهــا بســاطورة حلــم عــدة‬\n      ‫ضربــات علــى جانبــي رقبتهــا األميــن واأليســر حتــى فارقــت احليــاة وأن‬\n      ‫قصــده هــو قتلهــا والتخلــص منهــا بســبب املشــاكل التــي بينهمــا وصــدق‬\n      ‫إقــراره بذلــك شــرع ًا وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n      ‫بقتــل زوجتــه املواطنــة ‪...........‬عمــد ًا وعدوانـ ًا بســاطور حلــم وذلــك لألدلــة‬\n      ‫والقرائــن التاليــة ‪1‬ـ ـ إقــراره املنــوه عنــه املصــدق شــرع ًا علــى الصفحــة‬\n      ‫رقــم (‪ )9‬مــن ملــف التحقيــق رقــم (‪ )1‬لفــة رقــم (‪2 )37‬ـ ـ احملضــر املعــد‬\n      ‫مــن قبــل الدوريــات األمنيــة لفــة رقــم (‪3 )22‬ـ ـ إقــراره حتقيقـ ًا مبــا أشــير‬\n      ‫إليــه املــدون علــى الصفحــات رقــم (‪ ) 3 ،2‬مــن ملــف التحقيــق لفــة رقــم‬\n      ‫(‪4 )2‬ـ ـ التقريــر الطبــي الشــرعي املنــوه عنــه املــدون علــى اللفــات ( ‪ 57‬ـ ـ‬\n      ‫‪5 ) 61‬ـ ـ التقريــر الفنــي املصــور لفــة رقــم ( ‪6 ) 63‬ـ ـ التقرير الفني املصور‬\n      ‫واملرئــي لتمثيــل جرميــة القتــل مــن قبــل املتهــم لفــة (‪ )93‬وبالبحــث عــن‬\n      ‫ســوابقه عثــر لــه علــى ســابقة ضــرب أحــد األشــخاص بآلــة حــادة وقــد‬\n      ‫صــدر قــرار جلنــة إدارة الهيئــة رقــم (‪ )...........‬لعــام ‪1426‬ه ـ باملوافقــة علــى‬\n      ‫مــا انتهــى إليــه قــرار االتهــام رقــم ‪...........‬لعــام ‪1426‬ه ـ وحيــث إن مــا‬\n      ‫أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات صفــة القتــل واحلكــم عليــه‬\n      ‫مبــا قضــت بــه اإلرادة امللكيــة وفق ـ ًا ملــا ورد مــن قــرار مجلــس القضــاء‬\n      ‫األعلــى رقــم ‪ 3/106‬وتاريــخ ‪1408/04/23‬ه ـ املؤيــد باألمــر الســامي‬\n\n\n‫‪113‬‬\n\f‫رقــم ‪ 1197/4‬وتاريــخ ‪1409/06/12‬ه ـ وتشــديد العقوبــة عليــه ولــو‬\n‫بالقتــل تعزيــر ًا لشــناعة اجلرميــة التــي ارتكبهــا ( علمـ ًا بــأن احلــق اخلــاص‬\n‫ال زال قائم ـ ًا ) وبــاهلل التوفيــق هكــذا ادعــى كمــا حضــر املدعــي يف‬\n‫احلــق اخلــاص ‪......................‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪...........‬األصيــل عــن نفســه والوكيــل الشــرعي عــن ‪......................‬‬\n‫بالوكالــة الصــادرة مــن كتابــة عــدل اجلبيــل برقــم ‪...........‬يف‬\n‫‪1430/04/12‬ه ـ وعــن ‪...........‬بالوكالــة الصــادرة مــن كتابــة عــدل‬\n‫محافظــة األفــاج برقــم ‪...........‬يف ‪1430/04/15‬ه ـ وعــن ‪...........‬‬\n‫بالوكالــة الصــادرة مــن كتابــة عــدل جنــران برقــم ‪270506004046‬‬\n‫يف ‪1430/04/17‬ه ـ وعــن كل مــن ‪ ...........‬و‪ ...........‬و‪ ...........‬بنــات‬\n‫‪ ............‬و‪...........‬بالوكالــة الصــادرة مــن كتابــة عــدل جنــران برقــم‬\n‫‪...........‬يف ‪1430/04/17‬ه ـ وعــن ‪...........‬بالوكالــة الصــادرة من كتابة‬\n‫عــدل جنــران برقــم ‪...........‬يف ‪1430/04/18‬ه ـ وعــن ‪...........‬بالوكالــة‬\n‫الصــادرة مــن كتابــة عــدل جنــران برقــم ‪...........‬يف ‪1430/04/19‬ه ـ‬\n‫واملدعــي وموكليــه هــم ورثــة ‪......................‬مبوجــب صــك حصــر الورثــة‬\n‫الصــادر مــن احملكمــة العامة بنجران برقــم ‪...........‬يف ‪1429/03/23‬هـ‬\n‫املتضمــن وفــاة ‪......................‬بتاريــخ ‪1429/02/11‬ه ـ وانحصــار إرثــه‬\n‫يف زوجتــه ‪......................‬ويف أوالده البالغــن ســن الرشــد‬\n‫‪...........‬و‪...........‬و‪ ...........‬و‪ ...........‬و‪ ...........‬و‪ ...........‬و‪...........‬و‪...........‬‬\n‫و‪ ...........‬و‪ ...........‬و‪ ...........‬الــذي تــويف بعــد ابنتــه ‪...........‬املنحصــر إرثهــا‬\n‫مبوجــب صــك حصــر اإلرث الصــادر مــن احملكمــة العامــة بنجــران‬\n‫برقــم ‪...........‬يف ‪1427/02/14‬ه ـ واملتضمــن وفــاة ‪......................‬‬\n‫وانحصــار إرثهــا يف والدهــا ‪...........‬ويف والدتهــا ‪...........‬ويف أوالدهــا‬\n\n\n                                                                                                      ‫‪114‬‬\n\f      ‫القاصريــن ‪.................................‬املولــود بتاريــخ ‪1415/06/09‬ه ـ‬\n      ‫و‪........... ...........‬املولــودة بتاريــخ ‪1417/07/14‬ه ـ و‪...........‬املولــودة‬\n      ‫بتاريــخ ‪1425/09/02‬ه ـ والوكيــل أيضـ ًا عــن ‪......................‬بعــد بلوغــه‬\n      ‫بالوكالــة الصــادرة مــن كتابــة عــدل جنــران برقــم ‪...........‬يف‬\n      ‫‪1430/08/11‬ه ـ وعــن ‪......................‬بعــد بلوغهــا بالوكالــة الصــادرة‬\n      ‫مــن كتابــة عــدل جنــران برقــم ‪...........‬يف ‪1433/10/23‬ه ـ املخــول لــه‬\n      ‫فيهــا حــق املطالبــة وإقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعوى‬\n      ‫والــرد عليهــا واإلقــرار واإلنــكار والصلــح وقبــول األحــكام ونفيهــا‬\n      ‫واالعتــراض عليهــا واملطالبــة بالقصــاص مــن القاتــل ‪......................‬وأمــا‬\n      ‫الوارثــة ‪...........‬فهــي ابنــة املدعــى عليــه القاتــل وجميــع الــوكاالت تخــول‬\n      ‫املدعــي حــق املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوى‬\n      ‫ضــد ‪...........‬واملطالبــة بالقصــاص ولــه احلــق يف ســماع الدعــاوى والــرد‬\n      ‫عليهــا واإلقــرار واإلنــكار والصلــح وقبــول احلكــم أو االعتــراض عليــه‬\n      ‫وبســؤاله عــن دعــواه وموكليــه قــال إن هــذا املدعــى عليــه احلاضــر‬\n      ‫‪...........‬قــام بقتــل مورثتنــا أختــي ‪......................‬وهــي زوجتــه وحتــت‬\n      ‫فراشــه وذلــك بضربهــا بســاطور اللحــم عــدة ضربــات يف رقبتهــا عمــد ًا‬\n      ‫عدوان ـ ًا ممــا أدى إلــى قتلهــا وذلــك بتاريــخ ‪1426/07/28‬ه ـ ولــه منهــا‬\n      ‫بنــت اســمها ‪...........‬أطلــب احلكــم بقتلــه قصاص ـ ًا لقــاء حقنــا اخلــاص‬\n      ‫هكــذا ادعــى وبعــرض دعــوى املدعــي العــام واملدعــي يف احلــق اخلــاص‬\n      ‫ا إنــه بتاريــخ‬     ‫أصالــة ووكالــة علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫‪1426/07/28‬ه ـ دخلــت علــى زوجتــي ‪......................‬وســمعتها تتصــل‬\n      ‫بجــوال معهــا فأخفتــه فســألتها عنــه فقالــت ليــس معــي جــوال فقمــت‬\n      ‫بتفتيــش املنــزل فلمــا وصلــت إلــى املــكان الــذي أخفــت فيــه اجلــوال يف‬\n\n\n‫‪115‬‬\n\f‫املطبــخ أخــذت زوجتــي ســكين ًا وأقبلــت علــي وضربتنــي يف يــدي اليمنــى‬\n‫فأخــذت ســاطور اللحــم مــن فــوق الثالجــة وضربتهــا بــه علــى رقبتهــا مــن‬\n‫اجلهــة اليمنــى ضربــة واحــدة فســقطت علــى األرض والــدم ينــزف مــن‬\n‫رقبتهــا وأنــا املتســبب الوحيــد يف وفاتهــا ولــم يشــاركني يف قتلهــا أحــد‬\n‫ولــم أكــن أقصــد قتلهــا ثــم أخــذت ابنتــي املدعــوة ‪...........‬وذهبــت بهــا‬\n‫إلــى أختــي يف ‪...........‬وزوجتــي املذكــورة ‪...........‬هــي أم ابنتــي ‪...........‬‬\n‫هكــذا أجــاب وبطلــب البينــة مــن املدعــي العــام واملدعــي يف احلــق اخلاص‬\n‫ا بينتــي مــا ذكرتــه يف الئحــة‬     ‫أصالــة ووكالــة أجــاب املدعــي العــام قائـ ً‬\n‫الدعــوى ومــا تضمنتــه أوراق املعاملــة هكــذا قــرر وأجــاب املدعــي يف‬\n‫ا بينتــي إقــرار املدعــى عليــه وأوراق‬      ‫احلــق اخلــاص أصالــة ووكالــة قائ ـ ً‬\n‫املعاملــة هكــذا قــرر فجــرى منــا االطــاع علــى أوراق املعاملــة ومنهــا‬\n‫إقــرار املدعــى عليــه املــدون علــى الصفحــة رقــم (‪ )9‬مــن دفتــر التحقيــق‬\n‫رقــم ( ‪ )1‬املرفــق لفــة رقــم ( ‪ ) 37‬واملصــدق شــرع ًا مــن احملكمــة العامــة‬\n‫بنجــران الصفحــة رقــم (‪ )8‬مــن نفــس الدفتــر ونصــه ( محضــر إقــرار‬\n‫واعتــراف بتاريــخ ‪1426/07/30‬ه ـ أقــر أنــا ‪...........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪...........‬وتاريــخ ‪1404/11/25‬ه ـ الصــادر‬\n‫مــن جنــران وأنــا بكامــل قــواي العقليــة املعتبــرة شــرع ًا مــن غيــر إكــراه‬\n‫وال إجبــار مــن أحــد وبطوعــي واختيــاري ال مجبــر وال مكــره بأننــي قــد‬\n‫قمــت بقتــل زوجتــي املدعــوة ‪...........‬ســعودي اجلنســية يــوم اجلمعــة‬\n‫‪1426/07/28‬ه ـ بســاطور حلــم وذلــك بعــد النقــاش الــذي حــدث بيننــا‬\n‫والنــزاع واشــتبكنا أنــا وهــي وبعدهــا ذهبــت مســرعة للمطبــخ وحلقــت‬\n‫بهــا وأخــذت لهــا ســكني حلــم تريــد قتلــي فقمــت وأخــذت الســاطور مــن‬\n‫فــوق الثالجــة باملطبــخ حيــث أن الثالجــة علــى مدخــل املطبــخ ثــم ضربتها‬\n\n\n                                                                                        ‫‪116‬‬\n\f      ‫بهــا أول ضربــة علــى رقبتهــا مــن اجلهــة اليســرى وســقطت مباشــرة ثــم‬\n      ‫قمــت بضربهــا بالســاطور بعــد ســقوطها عــدة ضربــات علــى جانبــي‬\n      ‫رقبتهــا األميــن واأليســر حتــى فارقــت احليــاة ثــم قمــت بتغطيتهــا بفــروة‬\n      ‫حيــث لــم تكــن ترتــدي مالبــس مــن الليــل ألننــا كنــا نائمــن علمـ ًا بأنــي‬\n      ‫لــم أكــن أعلــم كــم عــدد الضربــات التــي ضربتهــا بالســاطور وكان‬\n      ‫قصــدي هــو قتلهــا والتخلــص منهــا بســبب املشــاكل التــي بيننــا ثــم بعــد‬\n      ‫ذلــك قمــت ووضعــت الســاطور الــذي قتلــت ‪...........‬بــه يف املغســلة اليدويــة‬\n      ‫املؤديــة للمطبــخ يف املمــر وأخــذت ابنتــي الصغيــرة ‪...........‬التــي كانــت‬\n      ‫تشــاهدنا معــي وأقفلــت البيــت علــى زوجتــي بعــد قتلهــا وذهبــت لبيــت‬\n      ‫أختــي يف ‪...........‬وأعطيتهــا ابنتــي ‪...........‬ثــم ذهبــت واختبــأت يف عمــارة‬\n      ‫ال زالــت حتــت اإلنشــاء إلــى بعــد املغــرب وبعدهــا خرجــت مــن العمــارة‬\n      ‫إلــى بيــت قريــب منــي وقلــت لصاحــب البيــت بأننــي قتلــت زوجتــي وأرغــب‬\n      ‫يف تســليم نفســي للشــرطة هــذا كل مــا حــدث وعلــى هــذا جــرى التوقيــع‬\n      ‫منــي عليــه املقــر مبــا فيــه ‪...........‬إبهامــه ) أ ‪ .‬ه ـ وبعرضــه عليــه أجــاب‬\n      ‫ا غيــر صحيــح مــا ورد يف إقــراري أننــي ضربتهــا عــدة ضربــات‬              ‫قائ ـ ً‬\n      ‫والصحيــح هــي ضربــة واحــدة كمــا ذكــرت يف جوابــي ولــم أقصــد‬\n      ‫قتلهــا هكــذا أجــاب كمــا جــرى االطــاع على التقرير الطبي الشــرعي‬\n      ‫الصــادر مــن مركــز الطــب الشــرعي بنجــران برقــم ‪...........‬يف‬\n      ‫‪1426/08/13‬ه ـ املرفــق علــى اللفــات مــن ( ‪ ) 57‬حتــى ( ‪ ) 61‬ونــص‬\n      ‫احلاجــة منــه ( فقــرة الــرأي بتوقيــع الكشــف الطبــي الشــرعي الظاهــري‬\n      ‫علــى جثــة املدعــوة ‪...........‬والكشــف الشــعاعي والتحاليــل ومذكــرة‬\n      ‫الشــرطة أقــرر اآلتــي ‪1‬ـ ـ أن اإلصابــات املشــاهدة باجلســم ( بالــرأس‬\n      ‫والعنــق والقفــا وأعلــى الظهــر ) هــي جــروح قطعيــة معظمهــا عميــق‬\n\n\n‫‪117‬‬\n\f‫وبعضهــا ســطحي وهــي تنشــأ مــن اإلصابــة بجســم صلــب ذات نصــل حــاد‬\n‫‪2‬ـ ـ أن اإلصابــات القطعيــة املوجــودة باليديــن هــي جــروح تنــم عــن مقاومــة‬\n‫املجنــي عليهــا يف محاولــة منهــا القبــض علــى نصــل اآللــة احلــادة املوجــه‬\n‫إليهــا ‪3‬ـ ـ ســبب الوفــاة نزيــف دمــوي غزيــر نتيجــة اإلصابــات القطعيــة‬\n‫العميقــة املشــاهدة باجلســم ‪5‬ـ ـ ســلبية نتائــج التحاليــل بالنســبة للمســحة‬\n‫املهبليــة والســموم كمــا أن فصيلــة دم املذكــورة ( ‪ ) O‬الطبيــب‬\n‫الشــرعي مبنطقــة جنــران د‪ ........... /‬توقيعــه اخلتــم الرســمي مستشــفى‬\n‫جنــران العــام الطــب الشــرعي ) أ ‪ .‬ه ـ وبعرضــه علــى املدعــى عليــه أجــاب‬\n‫ا لــم أضربهــا إال مــرة واحــدة وليــس لــي علــم بغيــر ذلــك هكــذا‬          ‫قائ ـ ً‬\n‫أجــاب كمــا جــرى االطــاع علــى إقــرار املدعــى عليــه حتقيق ـ ًا املــدون‬\n‫علــى الصفحــات رقــم (‪ ) 3 ،2‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪)2‬‬\n‫وكــذا محضــر الدوريــات األمنيــة املرفــق لفــة رقــم (‪ )22‬وكــذا التقريــر‬\n‫الفنــي املصــور املرفــق لفــة رقــم (‪ )63‬وكــذا التقريــر الفنــي لتمثيــل‬\n‫اجلرميــة املرفــق لفــة رقــم (‪ )93‬فوجدناهــا مطابقــة ملــا جــاء يف دعــوى‬\n‫املدعــي العــام وبســؤال املدعــى عليــه عــن ســابقته املذكــورة يف دعــوى‬\n‫ا صحيحــة وقــد تبــت إلــى اهلل منهــا هكــذا‬         ‫املدعــي العــام أجــاب قائ ـ ً‬\n‫أجــاب وبعــرض العفــو أو الصلــح علــى املدعــي يف احلــق اخلــاص أصالــة‬\n‫ووكالــة وتبيــن مــا يف ذلــك مــن األجــر العظيــم حيــث كان النبــي صلــى‬\n‫ا ال نقبــل صلح ـ ًا‬ ‫اهلل عليــه وســلم يعــرض علــى أوليــاء الــدم أجــاب قائ ـ ً‬\n‫ونطلــب قتــل املدعــى عليــه هكــذا أجــاب ويف جلســة أخــرى حضــر‬\n‫املدعــي يف احلــق اخلــاص أصالــة ووكالــة واملدعــى عليــه وبســؤالهما هــل‬\n‫لــدى أحــد منهمــا مــا يــود إضافتــه أجــاب كل واحــد منهمــا مبفــرده‬\n‫ا ليــس لــدي ســوى مــا قدمــت هكــذا قــرروا وبعــرض العفــو أو‬               ‫قائ ـ ً‬\n\n\n                                                                                           ‫‪118‬‬\n\f      ‫الصلــح علــى املدعــي يف احلــق اخلــاص أصالــة ووكالــة للمــرة الثانيــة‬\n      ‫ا إننــا نطالــب بقتــل املدعــى عليــه وال نقبــل صلح ـ ًا هكــذا‬   ‫أجــاب قائ ـ ً‬\n      ‫أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n      ‫‪...........‬يف مجلــس القضــاء بقتــل زوجتــه ‪...........‬بضربهــا بســاطور اللحــم‬\n      ‫حتــى وفاتهــا وملــا جــاء يف إقــراره املصــدق شــرع ًا وملــا جــاء يف التقريــر‬\n      ‫الطبــي الشــرعي وملــا جــاء يف أوراق املعاملــة وإلقــرار املدعــي يف احلــق‬\n      ‫اخلــاص أصالــة ووكالــة أن للمدعــى عليــه بنتـ ًا اســمها ‪...........‬مــن زوجته‬\n      ‫املجنــي عليهــا كمــا تضمنــه صــك حصــر الورثــة املشــار إليــه وملــا قــرره‬\n      ‫أهــل العلــم رحمهــم اهلل كمــا يف املغنــي ( ج‪ [ )486/11‬فصــل ( لــو قتــل‬\n      ‫أحــد األبويــن صاحبــه ولهمــا ولــد لــم يجــب القصــاص ألنــه لــو وجــب‬\n      ‫لوجــب لولــده وال يجــب للولــد قصــاص علــى والــده ألنــه إذا لــم يجــب‬\n      ‫باجلنايــة عليــه فــأن ال يجــب لــه باجلنايــة علــى غيــره أولــى وســواء كان‬\n      ‫الولــد ذكــر ًا أو أنثــى أو كان للمقتــول ولــد ســواه أو مــن يشــاركه يف‬\n      ‫امليــراث أو لــم يكــن ألنــه لــو ثبــت القصــاص لوجــب لــه جــزء منــه وال‬\n      ‫ميكــن وجوبــه وإذا لــم يثبــت بعضــه ســقط كلــه ألنــه ال يتبعــض وصــار‬\n      ‫كمــا لــو عفــا بعــض مســتحقي القصــاص عــن نصيبــه منــه ] ونحــوه يف‬\n      ‫احلــادي الكبيــر للمــارودي ( ج ‪ )47/12‬ويف حاشــيتا قليــو بــي وعميــرة (‬\n      ‫ج‪ 150/14‬ـ ـ ‪ ) 151‬وألن املــرأة ضعيفــة وبحاجــة إلــى مــن يحميهــا وألن‬\n      ‫املنــاط بالرجــل حمايــة زوجتــه ومــن حتــت يــده مــن النســاء ولقولــه صلــى‬\n      ‫اهلل عليــه وســلم (( اســتوصوا بالنســاء خيــرا )) ولبشــاعة مــا أقــدم عليــه‬\n      ‫املدعــى عليــه مــن قتــل زوجتــه بهــذه الطريقــة وبحضــور ابنتهمــا الصغيــرة‬\n      ‫ومشــاهدتها ملــا حــدث والتــي ال يقــدم عليهــا إال مــن نزعــت مــن قلبــه‬\n      ‫الرحمــة وهــي امرأتــه وحتــت فراشــه وال مغيــث لهــا غيــره وال تســتطيع‬\n\n\n‫‪119‬‬\n\f‫أن تســتنجد بأحــد وليكــون عبــرة لغيــره مــن املعتديــن علــى محارمهــم‬\n‫الالتــي يأمــن علــى أرواحهــن مــن أزواجهــن وجلميــع ما ســبق فقد حكمنا‬\n‫مبــا يلــي أو ًال إدانــة املدعــى عليــه ‪...........‬بقتل زوجتــه ‪......................‬عمد ًا‬\n‫عدوان ـ ًا وذلــك بضربهــا بســاطور اللحــم عــدة ضربــات يف رقبتهــا ممــا‬\n‫أدى إلــى وفاتهــا ثانيـ ًا صــرف النظــر عــن طلــب املدعــي يف احلــق اخلــاص‬\n‫أصالــة ووكالــة قتــل املدعــى عليــه قصاصـ ًا وإفهامــه بــأن لــه وموكليــه‬\n‫املطالبــة بنصيبهــم يف ديــة مورثتهــم ثالثـ ًا قتــل املدعــى عليــه تعزيــر ًا وذلــك‬\n‫بضــرب عنقــه بالســيف حتــى املــوت وبإعــان احلكــم قــرر املدعــي عليــه‬\n‫عــدم القناعــة باحلكــم وطلــب تقــدمي الئحــة إعتراضيــة فأجيــب لطلبــه‬\n‫وافهــم بتعليمــات اإلســتئناف وقــرر املدعــي يف احلــق اخلــاص إعتراضــه‬\n‫وأفــاد أنــه علــى مطالبتــه بالقتــل قصاص ـ ًا بــدون الئحــة اعتراضيــة‬\n‫واملدعــي العــام القناعــة باحلكــم وقررنــا رفع املعاملة لإلســتئناف حســب‬\n‫التعليمــات وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/11/22‬ه ـ احلمــد هلل وحــده وبعــد يف‬\n‫يــوم اإلثنــن املوافــق‪ 1433/11/22‬ه ـ احلمــد هلل وحــده وبعــد فقد عادت‬\n‫املعاملــة مــن احملكمــة العليــا بكتــاب رئيســها رقــم ‪342069115‬‬\n‫وتاريــخ ‪1434/11/24‬ه ـ املرفــق بــه القــرار رقــم ‪ 1/1/232‬وتاريــخ‬\n‫‪1434/11/12‬ه ـ واملتضمــن ((وبدراســة الصــك الذكــور وأوراق‬\n‫املعاملــة قررنــا باألكثريــة املوافقــة علــى احلكــم وأمرنــا بالتظهيــر بذلك‬\n‫علــى الصــك والتهميــش بــه علــى ضبطــه وســجله واهلل املوفــق وصلــى اهلل‬\n‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن الدائــرة اجلزائيــة‬\n‫األولــى باحملكمــة العليــا عضــو ‪...........‬ختمــه وتوقيعــه عضــو‬\n‫‪......................‬ختمــه وتوقيعــه عضــو ‪...........‬ختمــه وتوقيعــة ولــي وجهــة‬\n\n\n                                                                                                  ‫‪120‬‬\n\f      ‫نظــر تتضمــن( أن مــا قــرره أصحــاب الفضيلــة مــن قتــل املدعــى عليــه‬\n      ‫تعزيــر ًا محــل نظــر لعــدم موجــب ذلــك وإذا كان القصــاص قــد ســقط‬\n      ‫عنــه ‪-‬بســبب أن مــن ضمــن ورثــة ‪...........‬هــذه ابنــة منهــا للمدعــى عليــه‬\n      ‫‪ -‬وهــو أقــوى مــن قتلــه تعزيــر ًا ممايتعــن معــه رجــوع أصحــاب الفضيلــة‬\n      ‫عمــا قــرروه وتعزيــره مبــا يالقــي جرمــه ملالحظــة ذلــك واهلل املوفــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ) عضــو‬\n      ‫‪......................‬ختمــه وتوقيعــة رئيــس الدائــرة ‪...........‬ختمــه وتوقيعه))أ‪.‬هـ‬\n      ‫وبنــاء عليــه قررنــا التهميــش علــى ضبطــه وســجله مبــا حلــق واهلل املوفــق‬\n      ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n      ‫‪1435/1/9‬ه ـ ‪ .‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n                                                                               ‫بعده ‪ ،‬وبعد ‪-:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائية اخلماســية الثانية مبحكمة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫احملكمــة العامــة بنجــران برقــم ‪ 341333023‬وتاريــخ ‪1434/6/17‬ه ـ‬\n      ‫املرفــق بهــا الصــك رقــم ‪ 33463560‬وتاريــخ ‪1433/11/23‬ه ـ الصــادر‬\n      ‫مــن أصحــاب الفضيلــة القضاة باحملكمــة العامة بنجران الشــيخ‪...........‬‬\n      ‫والشــيخ‪...................... /‬والشــيخ‪........... /‬املتضمــن دعــوى املدعــي العــام‬\n      ‫ضــد‪ ،...................... /‬املتهــم بقتــل زوجتــه املواطنة‪......................‬عمــد ًا‬\n      ‫وعدوانـ ًا بســاطور حلــم ‪ ،‬احملكــوم فيــه بقتــل املدعــى عليــه تعزيــر ًا وذلك‬\n                                                    ‫بضــرب عنقــه بالســيف حتــى املــوت‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n      ‫علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                              ‫وصحبــه وســلم ‪.‬‬\n\n\n‫‪121‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":108,"source_page_end":121,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"39bcee879497c269252a8447456cffd15f0f4aabc681beb41eee09487ddb36ae","normalized_text_hash":"bc1ea484602f17003e9d02512aa2884e46b789c2970dd444e4c00dbc35bd5880","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p108-33463560"},{"id":"dd22b5da-1009-58d9-bd2a-a08a4e61ecc2","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل -احلق اخلاص -اختصاص -عدم املراجعة يف احلق اخلاص -تدافع اختصاص بن المحكمة العامة واجلزائية -إثبات صفة القتل قضية تعزيرية من اختصاص اجلزائية ما لم تدخل تبعا يف قضية من اختصاص المحكمة العامة -عدم اختصاص نوعي -صرف النظر عن دعوى املدعي العام لعدم االختصاص النوعي.","document_number":"34214942","case_number":"33228116","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/5/18","year":"1434","subject":"قتل -احلق اخلاص -اختصاص -عدم املراجعة يف احلق اخلاص -تدافع اختصاص بن المحكمة العامة واجلزائية -إثبات صفة القتل قضية تعزيرية من اختصاص اجلزائية ما لم تدخل تبعا يف قضية من اختصاص المحكمة العامة -عدم اختصاص نوعي -صرف النظر عن دعوى املدعي العام لعدم االختصاص النوعي.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34214942 :‬تاريخه‪1433/5/18 :‬هـ‬\n                    ‫رقم الدعوى‪33228116:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34260613‬تاريخه‪1434/7/5 :‬هـ‬\n\n\n‫قتــل ‪ -‬احلــق اخلــاص ‪ -‬اختصــاص ‪ -‬عــدم املراجعــة يف احلــق اخلــاص‬\n‫‪ -‬تدافــع اختصــاص بــن احملكمــة العامــة واجلزائيــة ‪ -‬إثبــات صفــة‬\n‫القتــل قضيــة تعزيريــة مــن اختصــاص اجلزائيــة مــا لــم تدخــل تبعــا‬\n‫يف قضيــة مــن اختصــاص احملكمــة العامــة ‪ -‬عــدم اختصــاص نوعــي‬\n‫‪ -‬صــرف النظــر عــن دعــوى املدعــي العــام لعــدم االختصــاص النوعــي‪.‬‬\n\n\n\n\n                               ‫‪ -1‬املادة ‪ 126‬من نظام االجراءات اجلزائية‪.‬‬\n\n\n\n\n‫جــرى إحالــة املعاملــة مــن االدعــاء العــام للمحكمــة العامــة للنظر يف احلق‬\n‫العــام واخلــاص يف قضيــة قتــل حيــث يطلــب املدعــي العــام إثبــات صفــة‬\n‫القتــل ‪ ،‬لــم يراجــع أحــد يف احلــق اخلــاص ‪ ،‬وألن إحالتهــا للمحكمــة‬\n‫العامــة كان ألجــل النظــر يف احلــق اخلــاص وأمــا دعــوى املدعــي العــام‬\n‫وطلبــه إثبــات صفــة القتــل فــإن دخولهــا يف اختصــاص احملكمــة العامــة‬\n‫كان تبع ـ ًا للحــق اخلــاص ‪ ،‬عليــه وحيــث لــم يحضــر أحــد مــن املدعــن‬\n‫يف احلــق اخلــاص ‪ ،‬ولتعــذر النظــر يف احلــق اخلــاص واحلــال هــذه ‪ ،‬وألن‬\n‫قضيــة املدعــي العــام ال تدخــل يف اختصــاص احملكمــة ابتــداء وإمنــا تبعـ ًا‬\n‫لدعــوى املدعــن يف احلــق اخلــاص فيمــا لــو طالبــوا بالقصــاص لــذا فــا‬\n\n                                                                                   ‫‪122‬‬\n\f      ‫يحــق للمحكمــة العامــة النظــر ابتــداء يف قضيــة املدعــي العــام لتعــذر‬\n      ‫النظــر يف القضيــة األصــل والتــي مبوجبهــا دخــل طلــب اإلدعــاء العام تبعا‬\n      ‫يف واليــة احملكمــة العامــة ‪ ،‬عليــه فقــد جــرى بعــث األوراق للمحكمــة‬\n      ‫اجلزائيــة ‪ ،‬عــادت املعاملــة مــن احملكمــة اجلزائيــة دافعـ ًا قاضيهــا نظرها‬\n      ‫بعــدم اختصــاص احملكمــة اجلزائيــة بنظرهــا خاصــة وأن املدعــى‬\n      ‫عليهمــا لــم يســقط عنهمــا القــود ‪ ،‬صــدر قــرار مــن احملكمــة العامــة‬\n               ‫بعــدم االختصــاص ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدينــا‬\n      ‫نحــن ‪...........‬و‪...........‬و‪......................‬القائــم بعمــل ‪...........‬القضــاة‬\n      ‫باحملكمــة العامــة مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة إلينــا‬\n      ‫مــن فضيلــة الرئيــس برقــم واملقيــدة بأســاس احملكمــة برقــم وتاريــخ‬\n      ‫‪1433/3/30‬ه ـ الــواردة مــن االدعــاء العــام برقــم ‪ 15994‬وتاريــخ‬\n      ‫‪1433/3/27‬ه ـ ويف يــوم االثنــن ‪1434/4/29‬ه ـ فتــح ضبــط القضيــة‬\n      ‫إلجــراء الــازم نحــو التدافــع احلاصــل يف القضيــة املقامــة مــن االدعــاء‬\n      ‫العــام ضــد ‪...........‬بالســجل املدنــي رقــم ‪...........‬حيــث جــرى إحالتهــا‬\n      ‫للمحكمــة العامــة ابتــداء بطلــب النظــر يف احلــق اخلــاص وإثبــات صفــة‬\n      ‫القتــل ‪ ،‬عليــه وألن إحالتهــا للمحكمــة العامــة مبكــة كان ألجــل‬\n      ‫النظــر يف احلــق اخلــاص وأمــا دعــوى املدعــي العــام وطلبــه إثبــات صفــة‬\n      ‫القتــل فــإن دخولهــا يف اختصــاص احملكمــة العامــة كان تبع ـ ًا للحــق‬\n      ‫اخلــاص ‪ ،‬عليــه وحيــث لــم يحضــر أحــد مــن املدعــن يف احلــق اخلــاص ‪،‬‬\n      ‫ولتعــذر النظــر يف احلــق اخلــاص واحلــال هــذه ‪ ،‬وألن قضيــة املدعــي العــام‬\n\n‫‪123‬‬\n\f‫ال تدخــل يف اختصــاص احملكمــة ابتــداء وإمنــا تبعـ ًا لدعــوى املدعــن يف‬\n‫احلــق اخلــاص فيمــا لــو طالبــوا بالقصــاص لذا فال يحــق للمحكمة العامة‬\n‫النظــر ابتــداء يف قضيــة املدعــي العــام لتعــذر النظــر يف القضيــة األصــل‬\n‫والتــي مبوجبهــا دخــل طلبــه تبعــا يف واليــة احملكمــة العامــة ‪ ،‬عليــه‬\n‫فقــد جــرى بعــث األوراق للمحكمــة اجلزائيــة مبكــة فعــادت باخلطــاب‬\n‫رقــم ‪ 34630606‬وتاريــخ ‪1434/3/14‬ه ـ دافعـ ًا قاضيهــا نظرهــا بعــدم‬\n‫اختصــاص احملكمــة اجلزئيــة بنظرهــا خاصــة وأن املدعــى عليهمــا لــم‬\n‫يســقط عنهمــا القــود طبقــا لتعميــم معالــي وكيــل وزارة العــدل للشــؤون‬\n‫القضائيــة رقــم ‪/8‬ت‪ 95 /‬يف ‪1409/6/25‬ه ـ عليــه وألن مــا أشــار لــه‬\n‫فضيلتــه محــل نظــر ألمــور ‪ :‬األول ‪ /‬أن التعميــم املشــار لــه لــم ينــص فيــه‬\n‫بــأن نظــر احلــق العــام يف هــذه احلــال يكــون مــن اختصــاص احملكمــة‬\n‫العامــة فيرجــع يف ذلــك ألحــكام وقواعــد االختصــاص العامــة يف نظــام‬\n‫االجــراءات اجلزائيــة ‪ .‬الثانــي ‪ /‬أن ســقوط القــود كمــا يتحقــق بالتنــازل‬\n‫والعفــو يتحقــق بعــدم مراجعــة أوليــاء الــدم إذ ال ميكــن إنفــاذه بــا طلــب‬\n‫منهــم ‪ .‬الثالــث ‪ /‬أن مــا ورد يف تعميــم معالــي الوكيــل محمــول علــى قيام‬\n‫املطالبــة يف احلــق اخلــاص ‪ ،‬وهــذا غيــر متحقــق يف القضيــة محــل النظــر‬\n‫حيــث لــم يراجــع املدعــون باحلــق اخلــاص ممــا يفضــي جلعــل دعــوى املدعــي‬\n‫العــام معلقــة إلــى أمــد غيــر معلــوم وهــذا غيــر ســائغ فاالستشــهاد بــه يف‬\n‫غيــر محلــه ‪ .‬الرابــع ‪ « /‬بالنظــر إلــى املعنــى واملقصــود مــن التعميــم» فــإن‬\n‫طلــب إيقــاع العقوبــة التعزيريــة بعــد ســقوط القــود لئــا يتســاهل النــاس‬\n‫يف القتــل ‪ ،‬وأمــا إن اقتــص منــه بقتلــه فــا حاجــة لتعزيــره اكتفــاء مبــا‬\n‫حلقــه مــن جــزاء القتــل ‪ ،‬وهــذا املعنــى متحقــق يف هــذه الواقعــة فعــدم‬\n‫مراجعــة أصحــاب احلــق اخلــاص ومطالبتهــم بالقــود كتنازلهــم عنــه‬\n\n\n                                                                                       ‫‪124‬‬\n\f      ‫فيتعــن واحلــال هــذه النظــر يف مطالبــة املدعــي العــام إثبــات صفــة القتــل‬\n      ‫لــدى احملكمــة املختصــة لتطبيــق اإلرداة امللكيــة لتحقــق املعنــى املــراد‬\n      ‫يف كل ‪ ،‬والقيــاس كمــا هــو جــار يف األحــكام الشــرعية جــار يف‬\n      ‫األحــكام النظاميــة متــى وجــد الفــراغ النظامــي املعالــج لهــذه الواقعــة‬\n                                ‫كمــا هــو متقــرر يف علــم األنظمــة «علــم القانــون»‪.‬‬\n      ‫اخلامــس ‪ /‬إن حقيقــة مــا دفــع بــه فضيلتــه احلكــم بصــرف النظــر عــن‬\n      ‫دعــوى املدعــي العــام لعــدم حتقــق موجبهــا لديهــا وهــذا ال يكــون إال‬\n      ‫بعــد ســماع الدعــوى وصــرف النظــر عنهــا للمســوغ الــذي يــراه ‪.‬الســادس‬\n      ‫‪ :‬أن نظــر دعــوى املدعــي العــام ابتــداء طلبــه إثبــات صفــة القتــل إليقــاع‬\n      ‫العقوبــة التعزيريــة مــن قبــل احملكمــة العامــة مــن غيــر النظــر يف دعــوى‬\n      ‫املدعــي اخلــاص بطلــب القــود فيــه مخالفــة صريحــة للمــادة «‪»128‬‬\n      ‫مــن نظــام اإلجــراءات اجلزائيــة القاضيــة بــأن الدعــاوى التعزيريــة مــن‬\n      ‫اختصــاص احملكمــة اجلزئيــة حيــث لــم ينعقــد الســبب املوجــب لدخــول‬\n      ‫دعــوى املدعــي العــام يف اختصــاص احملكمــة العامــة ‪ .‬لــذا فقــد قررنــا‬\n      ‫باإلجمــاع صــرف النظــر عــن دعــوى املدعــي العــام لعــدم االختصــاص‬\n      ‫النوعــي لكونهــا مــن اختصــاص احملكمــة اجلزائيــة وبــه حكمنــا‬\n      ‫وبعرضــه علــى املدعــي العــام قــرر عــدم اعتراضــه ‪ ،‬وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n      ‫‪1434/04/29‬ه ـ ‪ .‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي‬\n                                                                          ‫بعــده وبعــد ‪-:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n      ‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى‬\n      ‫هــذه احملكمــة بكتــاب فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n\n\n‫‪125‬‬\n\f‫املكرمــة رقــم(‪ )34/659509‬وتاريخ(‪1434/6/18‬هــ) املرفــق‬\n‫بهــا القــرار رقم(‪)34214942‬وتاريخ(‪1434/5/18‬هـ)الصــادر مــن‬\n‫أصحــاب الفضيلــة القضــاة باحملكمــة العامــة مبكــة املكرمــة‬\n‫دعــوى‬         ‫الشيخ‪.........../‬والشيخ‪.........../‬والشــيخ‪،.........../‬املتضمن‬\n‫املدعــي العــام ضد‪.........../‬ســعودي اجلنســية ‪ ،‬احملكــوم فيــه مبــادون‬\n‫باطنه‪،‬وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم‬\n‫‪ ،‬واهلل املوفق‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                 ‫‪126‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":122,"source_page_end":126,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bad500c824747e65406ef84be996b6374e56bcb5069a5aec35ca16e445a350f5","normalized_text_hash":"eec70fedf4fb8f8bfb353273bfbc40ac9eaf37b52e3cd3f109f8e2fa0a40ed76","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p122-34214942"},{"id":"110c3c75-7b27-5758-ba74-9160a0c4f1b2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة بالقصاص يف حق خاص -إنكار املدعى عليه -قيام قرائن ال تكفي يف اإلدانة وال قيام موجب اللوث -تغليظ اليمن بتكرارها خمسون مرة -رفض املدعن اليمن -عدم وجود بينة موصلة للمدعين -عدم ثبوت إدانة املدعى عليه -رد الدعوى لعدم ثبوت إدانة املدعى عليه.","document_number":"33306057","case_number":"33410367","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/18","year":"1434","subject":"مطالبة بالقصاص يف حق خاص -إنكار املدعى عليه -قيام قرائن ال تكفي يف اإلدانة وال قيام موجب اللوث -تغليظ اليمن بتكرارها خمسون مرة -رفض املدعن اليمن -عدم وجود بينة موصلة للمدعين -عدم ثبوت إدانة املدعى عليه -رد الدعوى لعدم ثبوت إدانة املدعى عليه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 33306057 :‬تاريخه‪1433/06/18 :‬هـ رقم‬\n                              ‫الدعوى‪33410367:‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34338103:‬‬\n                          ‫تاريخه‪1434/10/22 :‬هـ‬\n\n\n      ‫مطالبــة بالقصــاص يف حــق خــاص ‪ -‬إنــكار املدعــى عليــه ‪ -‬قيــام قرائــن‬\n      ‫ال تكفــي يف اإلدانــة وال قيــام موجــب اللــوث ‪ -‬تغليــظ اليمــن بتكرارهــا‬\n      ‫خمســون مــرة ‪ -‬رفــض املدعــن اليمــن ‪ -‬عــدم وجــود بينــة موصلــة‬\n      ‫للمدعيــن ‪ -‬عــدم ثبــوت إدانــة املدعــى عليــه ‪ -‬رد الدعــوى لعــدم ثبــوت‬\n                                                               ‫إدانــة املدعــى عليــه‪.‬‬\n\n\n\n\n      ‫‪ -1‬البهوتــي يف كشــاف القنــاع «‪(:»13/470‬ومتــى ادعــى أحــد القتــل‬\n      ‫عمــد ًا أو غيــره مــع عــدم اللــوث أو وجــد قتيــل يف موضــع فادعــى أوليــاؤه‬\n      ‫علــى قاتــل مــع عــدم اللــوث حلــف املدعــى عليــه ميينــا واحــدة وبــرئ»‬\n                                                                                  ‫ا‪ -‬هـ‬\n      ‫‪ -2‬ابــن قدامــة يف املغنــي (‪ »: )12/189‬إذا وجــد قتيــل يف موضــع ‪،‬‬\n      ‫فادعــى أوليــاؤه قتلــه علــى رجــل أو جماعــة ولــم تكــن بينهــم عــداوة وال‬\n      ‫لــوث فهــي كســائر الدعــاوى إن كانــت لهــم بينــة حكــم لهــم بهــا وإال‬\n      ‫فالقــول قــول املنكــر وبهــذا قــال مالــك والشــافعي وابــن املنــذر» ا‪-‬ه ـ‬\n      ‫وقــال يف موضــع آخــر (‪ « :)12/191‬واليمــن واحــدة ألنــه يعضدهــا‬\n      ‫الظاهــر واألصــل فلــم تغلــظ وعــن أحمــد يشــرع خمســون ميينــا ألنهــا‬\n      ‫دعــوى يف القتــل فــكان املشــروع فيهــا خمســون ميينــا كمــا لــو كان‬\n                               ‫بينهــم لــوث وللشــافعي قــوالن علــى ذلــك» ا‪-‬ه ـ‬\n\n\n                                                                                          ‫‪136‬‬\n\f      ‫تقــدم املدعــون بدعــوى ضــد املدعــى عليــه لقيامــه بقتــل مورثهــم عمــدا‬\n      ‫وعدوانــا بطعنــه يف فخــذه األميــن بــأداة حــادة أدت لوفاتــه وطلبــوا احلكــم‬\n      ‫عليــه بالقصــاص‪ ،‬أنكــر املدعــى عليــه الدعــوى جملــة وتفصيــا وقــرر‬\n      ‫بأنــه ال يعــرف مــن قتلــه ‪ ،‬قــرر وكيــل املدعــن بــأن بينتــه تتلخــص يف‬\n      ‫أن املدعــى عليــه كان آخــر مــن اتصــل عليــه وهروبــه مــن الشــرطة‬\n      ‫واالدعــاء العــام وأن مفاتيــح منزلــه وجــدت بســيارة مورثهــم وتبــن وجــود‬\n      ‫خــاف بــن املدعــى عليــه وزوجتــه لقيــام مــورث املدعــن باالتصــال علــى‬\n      ‫زوجتــه يف الليلــة التــي تســبق مقتلــه وقيــام املدعــى عليــه ببيــع جــوال‬\n      ‫زوجتــه وضربهــا ليلــة مقتلــه بســاعات ‪ ،‬كمــا تبــن أن املدعــى عليــه‬\n      ‫علــى عالقــة كبيــرة مــع املقتــول وتربطهمــا عالقــة صادقــة حميمــة ‪،‬‬\n      ‫لــم جتــد اللجنــة القضائيــة يف الدعــوى قرائــن تــورث غلبــة الظــن بــأن‬\n      ‫املدعــى عليــه هــو القاتــل للمجنــي عليــه ‪ ،‬وال ينبغــي أن يحلــف املدعــي‬\n      ‫للقتــل إال بعــد قيــام غلبــة ظـ ٍـن تقــارب اليقــن فاملدعــى عليــه لــم يشــاهد‬\n      ‫مــع املجنــي عليــه‪ ،‬وليــس هنــاك عــداوة توجــب القتــل بــل األمــر علــى‬\n      ‫العكــس مــن ذلــك فهنــاك عالقــة حميميــة بينهمــا إضافــة إلــى أن وجــود‬\n      ‫خــاف بــن املدعــى عليــه وزوجتــه بســبب قيــام املجنــي عليــه باالتصــال‬\n      ‫علــى جــوال زوجــة املدعــى عليــه فــا يوجــد إقــرار صريــح مــن املدعــى‬\n      ‫عليــه وزوجتــه بذلــك ‪ ،‬وهــذا األمــر مجــرد احتمــال كمــا أن ورود‬\n      ‫اتصــال مــن جــوال املجنــي عليــه جلــوال زوجــة املدعــى عليــه أمــر غيــر‬\n      ‫مســتغرب كــون بينهمــا عالقــة وصداقــة كبيــرة ‪ ،‬وإلنــكار املدعــى‬\n      ‫عليــه قيامــه بقتــل مــورث املدعــن ومبــا أن املدعــي باحلــق اخلــاص ال‬\n\n‫‪137‬‬\n\f‫بينــة موصلــة لــه علــى دعــواه وألن اليمــن توجهــت علــى املدعــى عليــه‬\n‫واســتعد بأدائهــا إال أنــه لــم يقبــل املدعــي أصالــة ووكالــة ميــن املدعــى‬\n‫عليــه لــذا فقــد قــررت احملكمــة مــا يلــي‪ :‬أوال‪ :‬عــدم ثبــوت إدانــة املدعــي‬\n‫عليــه بالقتــل‪ .‬ثانيــا‪ :‬صــرف النظــر عــن طلــب املدعــي أصالــة ووكالــة‬\n‫لعــدم ثبــوت موجبــه‪ .‬ثالثــا‪ :‬إفهــام املدعــي أصالــة ووكالــة بــأن لــه ميــن‬\n‫املدعــى عليــه متــى طلبهــا ولــه املطالبــة بالديــة يف مواجهــة بيــت املــال بعــد‬\n‫االســتئذان مــن املقــام الســامي وبذلــك حكمــت ‪ ،‬بعرضــه علــى املدعــى‬\n‫أصالــة ووكالــة لــم يقتنــع وطلــب رفعهــا حملكمــة االســتئناف ووعــد‬\n‫بتقــدمي الئحــة اعتراضيــة فأجيــب لطلبــه وأفهــم بالتعليمــات بينمــا قــرر‬\n‫املدعــى عليــه القناعــة‪ ،‬طلبــت محكمــة االســتئناف إعــادة التحقيــق‬\n‫مــع املدعــى عليــه وزوجتــه للتحقــق مــن أمــر املفتــاح ‪ ،‬عــادت املعاملــة‬\n‫مــن هيئــة التحقيــق بعــدم الوصــول لنتيجــة جديــدة ‪ ،‬صــدق احلكــم مــن‬\n                                                              ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلدينــا نحــن قضــاة املشــترك لدينــا نحــن قضــاة‬\n‫املشــترك يف احملكمــة العامــة بخميــس مشــيط ‪...........‬و‪.....................‬‬\n‫‪.‬و‪ ...........‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بخميــس مشيط‪/‬املســاعد برقــم وتاريــخ ‪ 1433/06/17‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1433/06/17‬ه ـ ففــي يــوم الثالثــاء‬\n‫املوافــق‪ 1433/06/17‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 : 21‬وفيهــا‬\n‫حضــر ‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...........‬‬\n‫أصال ـ ًة عــن نفســه وبوكالتــه عــن ورثــة ابنــه ‪......................‬املذكوريــن‬\n\n                                                                                          ‫‪138‬‬\n\f      ‫يف صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪...........‬‬\n      ‫يف ‪1429/11/12‬ه ـ واملتضمــن وفــاة ‪......................‬ســجل مدنــي رقــم‬\n      ‫(‪ )...........‬وانحصــار إرثــه يف والــده ‪...........‬ووالدتــه ‪......................‬ويف‬\n      ‫زوجتــه ‪...........‬ويف أوالده منهــا وهــم ‪...........‬املولــودة يف ‪1423/3/8‬ه ـ‬\n      ‫‪...........‬املولــود يف ‪1425/6/7‬ه ـ و‪...........‬املولــودة يف ‪1428/2/2‬ه ـ‬\n      ‫‪...........‬املولــود بتاريــخ ‪1429/12/1‬ه ـ أ‪-‬ه ـ مبوجــب وكالتــه عــن‬\n      ‫جميــع الورثــة وعــن زوجــة ابنــه ‪...........‬الوليــة علــى القصــار املذكوريــن‬\n      ‫يف صــك حصــر الورثــة وهــذه الوكالــة صــادرة مــن كتابــة العــدل‬\n      ‫بخميــس مشــيط برقــم ‪...........‬يف ‪1433/3/29‬ه ـ واملخــول لــه فيهــا‬\n      ‫مراجعــة احملكمــة العامــة بخميــس مشــيط للمرافعــة واملدافعــة‬\n      ‫وحضــور اجللســات وتقــدمي البينــات والطعــن فيهــا وقبــول األحــكام‬\n      ‫واالعتــراض عليهــا واملطالبــة بالقصــاص واســتيفاءه مــن قاتــل مورثنــا‬\n      ‫‪...........‬ومبوجــب واليــة املــرأة ‪...........‬علــى أوالدهــا القاصريــن ‪...........‬‬\n      ‫املولــودة يف ‪1423/3/8‬ه ـ و‪ ...........‬املولــود يف ‪1425/6/7‬ه ـ و‪...........‬‬\n      ‫املولــودة يف ‪1428/2/2‬ه ـ الصــادرة مــن محكمــة خميــس مشــيط‬\n      ‫برقــم ‪...........‬يف ‪1429/11/12‬ه ـ التــي تخولهــا املطالبــة بالقصــاص‬\n      ‫واســتيفاءه ومبوجــب واليــة املــرأة ‪ ...........‬علــى ابنهــا ‪...........‬املولــود يف‬\n      ‫‪1429/12/1‬ه ـ وهــذه الواليــة صــادرة مــن محكمــة خميــس مشــيط‬\n      ‫برقــم ‪...........‬يف ‪1430/10/23‬ه ـ التــي تخولهــا املطالبــة بالقصــاص‬\n      ‫واســتيفاءه وادعــى علــى احلاضــر معــه ‪...........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )...........‬قائــا يف دعــواه عليــه إن هــذا احلاضــر‬\n      ‫قــام بقتــل مورثــي ومــورث موكلــي عمــد ًا عدوانــا وذلــك عــن بطعنــه‬\n      ‫يف فخــذه اليمنــى بــأداة حــادة أدت إلــى مقتلــه عمــدا عدوانــا أطلــب‬\n\n\n‫‪139‬‬\n\f‫احلكــم علــى هــذا احلاضــر بالقتــل قصاصــا هــذه دعــواي وبعــرض مــا‬\n‫جــاء يف دعــوى املدعــي أصالــة ووكالــة علــى املدعــى عليــه أجــاب بقولــه‬\n‫ا فأنــا‬ ‫مــا ذكــره املدعــي أصالــة ووكالــة غيــر صحيــح جملــة وتفصي ـ ً‬\n‫لــم أقتــل مــورث هــذا احلاضــر وال أعــرف مــن قتلــه وليــس لــي عالقــة‬\n‫مبقتلــه ال مــن قريــب وال مــن بعيــد هكــذا أجــاب فجــرى ســؤال املدعــي‬\n‫أصالــة ووكالــة عــن بينتــه فقــال لــدي بينــة وهــي أن املدعــى عليــه‬\n‫كان آخــر مــن اتصــل مبورثــي كمــا أنــه هــرب مــن الشــرطة وهــرب‬\n‫مــن االدعــاء العــام كمــا أن مفاتيــح منزلــه وجــدت علــى طبلــون ســيارة‬\n‫مورثــي وباقــي البينــات هــي مــا ورد يف لفــات املعاملــة ليــس لــدي بينــة‬\n‫غيرهــا فجــرى الرجــوع للمعاملــة فوجدنــا بهــا مــا يلــي ‪ :‬أو ًال ‪:‬الئحــة‬\n‫املدعــي العــام واملتضمنــة إنــه يف حوالــي الســاعة السادســة والنصــف مــن‬\n‫صبــاح يــوم اجلمعــة املوافــق ‪1429/8/28‬هـ ـ تبلــغ مركــز شــرطة ‪...........‬‬\n‫عــن طريــق العمليــات األمنيــة أنــه أثنــاء مســح إحــدى الدوريــات األمنيــة‬\n‫لــوادي ‪...........‬شــرق حــي ‪...........‬مبحافظــة خميــس مشــيط بالقــرب مــن‬\n‫الكوبــري اجلديــد املــؤدي إلــى حــي ‪...........‬مــن اجلهة اجلنوبيــة للبحث عن‬\n‫املجهولــن مت مشــاهدة ســيارة نــوع ‪ .......‬متوقفــة وجميــع أبوابهــا مفتوحــة‬\n‫وبالوصــول لهــا شــوهد بالقــرب منهــا شــخص ملقــى علــى ظهــره بــه آثــار‬\n‫دمــاء بســبب وجــود طعنــة يف فخــذه األميــن وباالنتقــال ملســرح اجلرميــة‬\n‫واملعاينــة مــن قبــل ضابــط خفــر مركــز شــرطة ‪...........‬برفقــة مديــر‬\n‫شــرطة محافظــة خميــس مشــيط ومديــر مركــز شــرطة ‪...........‬وفنــي‬\n‫األدلــة اجلنائيــة وبالوصــول للموقــع شــوهدت ســيارة ‪ ......‬موديــل (‪).......‬‬\n‫حتمــل اللوحــة رقــم (‪ )...........‬بيضــاء اللــون واقفــة علــى حافــة طريــق‬\n‫ترابــي مــن اجلهــة الغربيــة وأبوابهــا مفتوحــة وبجوارهــا مــن اجلهــة الشــرقية‬\n\n\n                                                                                       ‫‪140‬‬\n\f      ‫شــخص مســتلقي علــى ظهــره ملطــخ بالدمــاء وبــه طعنــة يف فخــذه األميــن‬\n      ‫واتضــح أنــه قــد فــارق احليــاة واتضــح أنــه يدعــى‪ /‬ع‪ , ...........‬ســعودي‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )...........‬يبلــغ مــن العمــر (‪)35‬‬\n      ‫عام ـ ًا ومبعاينــة الســيارة وجــدت علــى احلافــة الغربيــة للطريــق الترابــي‬\n      ‫الــذي كانــت تســير عليــه يف اجلهــة الغربيــة مــن الــوادي حيــث كان‬\n      ‫متجه ـ ًا مــن اجلنــوب إلــى الشــمال وعلــى مســافة حوالــي عشــرون متــر ًا‬\n      ‫قبــل وقوفهــا انحرفــت الســيارة لليســار عــن الطريــق حتــى اصطدمــت‬\n      ‫بشــجرة صغيــرة علــى حافــة الطريــق ووقفــت عندهــا ‪ ,‬مقدمتهــا للشــمال‬\n      ‫ومؤخرتهــا للجنــوب وباملوقــع عــدد مــن النفايــات ووجــد الكفــر األيســر‬\n      ‫اخللفــي مبنشــر وقــد وجــدت أبــواب الســيارة مفتوحــة وشــوهدت دمــاء‬\n      ‫علــى مرتبــة الســائق كثيــرة وكذلــك علــى مرتبــة الراكــب واملرتبــة‬\n      ‫اخللفيــة وبالتحديــد يف اجلــزء الــذي بعــد مرتبــة الســائق يف اجلهــة اليســرى‬\n      ‫وعلــى الكبــوت ووجــد مفتــاح الســيارة (بالســوتش) ويف وضــع التشــغيل‬\n      ‫كمــا وجــد جــوال نــوع ‪ )..…( ....‬علــى الطبلــون عائــد للقتيــل بجــوار‬\n      ‫مرتبــة الســائق مــن اجلهــة اليســرى بيــت ســكني حربــة أســود بطــول‬\n      ‫حوالــي نصــف متــر ووجــد عنــد دعاســة أرجــل الراكــب فــردة حــذاء‬\n      ‫شــرقية اتضــح أنهــا للقتيــل وكذلــك وجــد علــى طبلــون الســيارة أمــام‬\n      ‫الراكــب نظــارة شمســية ومفاتيــح كمــا وجــد أيض ـ ًا بــدرج الســيارة‬\n      ‫محفظتــه بنيــة اللــون ووجــد بداخلهــا األشــياء التاليــة ‪)1:‬اســتمارة ســيارة‬\n      ‫نــوع ‪ .....‬موديــل (‪ )......‬رقــم اللوحــة (‪ )2 )...........‬بطاقــة األحــوال ‪)3 .‬‬\n      ‫رخصــة ســياقة مدنيــة باســمه ‪ )4 .‬رخصــة ســياقة عســكرية باســمه ‪)5‬‬\n      ‫بطاقــة عمــل عســكرية باســمه ‪ )6‬صــراف البنــك ‪ ......‬باســمه ‪ )7‬عــدد‬\n      ‫أربعــة أرقــام جــوال (‪2‬ســواء ‪ 2 +‬جــوال عــام) ‪)8‬شــريحة اتصــال ســواء‬\n\n\n‫‪141‬‬\n\f‫عــدد اثنــن وبتفتيــش الســيارة لــم يضبــط بهــا أي شــيء مــن املمنوعــات‬\n‫أو احملرمــات ســوى ثــاث أكيــاس صغيــرة يشــتبه أن يكــون مــن مــادة‬\n‫التنبــاك ومبعاينــة اجلثــة وتفتيشــها وجــد القتيــل مســتلقي علــى ظهــره يف‬\n‫اجلهــة الشــرقية مــن الســيارة ورأســه باجتــاه الشــمال الشــرقي وأرجلــه‬\n‫باجتــاه اجلنــوب الغربــي يرتــدي ثــوب أبيــض وســروال أبيــض وفنيلــة‬\n‫نصــف كــم بيضــاء جميعهــا ملطخــة بالدمــاء والثــوب مرفــوع حتــى‬\n‫الوســط حيــث كان الســروال واضــح كاشــف الــرأس وحــايف القدمــن‬\n‫لــه ذقــن متوســط وشــعر رأســه أســود متوســط الطــول واألرجــل ليســت‬\n‫علــى اســتقامتها وإمنــا كانــت ملتقيــة عنــد الكعبــن علــى شــكل معــن‬\n‫وشــوهد بالفخــذ األميــن جــرح طعنــي طولــه حوالــي (‪3‬ســم) تقريبـ ًا وفوقــه‬\n‫جرحــن وخزتــن صغيــرة غيــر نافــذة وشــوهد كدمــة بالقــرب مــن‬\n‫الثــدي األميــن وشــوهد مقابــل هــذه اإلصابــات متزقــات مبالبــس القتيــل‬\n‫وشــوهد ســحج خطــي بســيط بالرقبــة ولــم يشــاهد باجلثــة خالفهــا ســوى‬\n‫أن عمــوم جســمه ملطــخ بالدمــاء وباألخــص األجــزاء الســفلية وبتفتيــش‬\n‫مالبســه وجــد يف جيــب ثوبــه العلــوي علــى مبلــغ وقــدره (‪ )675‬ســتمائة‬\n‫وخمســة وســبعون ريــا ًال ويف اجليــب اجلانبــي األيســر وجــد مبلــغ (‪)50‬‬\n‫خمســون ريــال ورقــة واحــدة وكذلــك بجــوار اجلثــة مــن اجلهــة اليمنــى‬\n‫عنــد الفخــذ األميــن جــوال ‪ ...‬اتضــح أنــه عائــد للمجنــي عليــه ومــن املعاينــة‬\n‫يتضــح أن القتيــل كان يســير بالســيارة بعــد إصابتــه وانحرفــت عــن‬\n‫الطريــق الــذي كانــت تســير عليــه حتــى اصطدمــت بالشــجرة وتوقفــت‬\n‫عندهــا وأن املذكــور لفــظ أنفاســه يف املوقــع وذلــك كمــا شــوهد يف‬\n‫املوقــع وكذلــك مــن حركــة أقدامــه يف التــراب أثنــاء منازعتــه للمــوت‬\n‫واحتكاكهــا بهــا ومت رفــع جميــع اآلثــار التــي باملوقــع وكذلــك‬\n\n\n                                                                                         ‫‪142‬‬\n\f      ‫البصمــات والتصويــر مــن قبــل فنــي األدلــة كمــا جــرى اســتدعاء‬\n      ‫الطبيــب الشــرعي ملعاينــة اجلثــة باملوقــع وقــد حضــر وشــاهدها بالوضــع‬\n      ‫الــذي وجــدت عليــه ومت الكشــف عليــه مــن قبلــه باملوقــع كمــا جــرى‬\n      ‫اســتدعاء قصــاص األثــر ملعاينــة املوقــع (ولــم يتضــح وجــود أي آثــار تفيــد‬\n      ‫القضيــة) ولــم يتــم العثــور باملوقــع وال األماكــن املجــاورة للموقــع علــى‬\n      ‫فــردة حــذاء القتيــل األخــرى وكذلــك األدلــة املســتخدمة يف اجلرميــة ‪...‬‬\n      ‫كمــا ورد التقريــر الطبــي الشــرعي رقــم (‪ )...........‬بخصــوص فحــص‬\n      ‫املالبــس اخلاصــة باملجنــي عليــه واملتضمــن الــرأي علــى النحــو التالــي ‪1:‬‬\n      ‫‪ -‬وجــود ثالثــة قطــوع حــادة ومســتوية احلــواف واقعــة مبنتصــف البــدن‬\n      ‫األمامــي للثــوب األبيــض العائــد للمجنــي عليــه ويجــوز حدوثهــا مــن‬\n      ‫جــراء الضــرب علــى مواضــع حدوثهــا باملالبــس باســتخدام أداة حــادة‬\n      ‫‪ - 2‬وجــود قطــع حــاد ومســتوي‬                       ‫كســكني أو مــا شــابهها‪.‬‬\n      ‫احلــواف مبقدمــة أســفل الرجــل اليمنــى للســروال األبيــض القصيــر‬\n      ‫العائــد للمجنــي عليــه ويجــوز حدوثــه مــن جــراء الضــرب علــى موضــع‬\n      ‫حدوثــه بالســروال باســتخدام أداة حــادة كســكني أو مــا شــابهها‪3 .‬‬\n      ‫‪ -‬بفحــص الفانيلــة الداخليــة البيضــاء اللــون العائــدة للمجنــي عليــه لــم‬\n                               ‫يتبــن وجــود أي ثقــوب أو قطــوع أو متزقــات أ‪-‬هــ‪.‬‬\n      ‫ثاني ـاً‪ :‬وجدنــا بهــا علــى لفــة رقــم (‪ 105‬ــ‪ )110‬مــن الدوســية رقــم (‪)2‬‬\n      ‫تقريــر الطــب الشــرعي رقم‪)...........‬بتاريــخ ‪1429/10/4‬ه ـ الصــادر مــن‬\n      ‫مركــز الطــب الشــرعي مبنطقــة عســير املتضمــن مــا يلــي ‪-1:‬وجــود‬\n      ‫جــرح طعنــي حيــوي وحديــث ذو حــواف حــادة ومســتوية ومنتظمــة‬\n      ‫ومتباعــدة عــن بعضهــا واألنســجة الغائــرة لهــا جهــة القــاع مقطوعــة قطع ًا‬\n      ‫مســتوي احلــواف يقــع بوضــع مائــل (مــن أنســية وأعلــى إلــى الوحشــية‬\n\n\n‫‪143‬‬\n\f‫وأســفل ) بطــول حوالــي ‪3,5‬ســم يقــع مبقدمــة أنســية أعلــى املثلــث‬\n‫الســفلي مــن الفخــذ األميــن وطرفــه الســفلي يعلــو مقــدم مفصــل الركبــة‬\n‫اليمنــى بحوالــي ‪12‬ســم ‪....‬الــخ ‪-2‬آثــار إصابيــة ذات طبيعــة رضيــة بأعلــى‬\n‫جــدار الصــدر حدثــت نتيجــة تعــرض املتوفــى للضــرب بجســم راض أيــا‬\n‫كان نوعــه ‪-3‬ســحج احتكاكــي بأعلــى مقدمــة يســار العنــق بطــول‬\n‫(‪7‬ســم) و(‪ )2‬جــرح وخــزي بأعلــى مقــدم الفخــذ األميــن يحــدث بجســم‬\n‫مدبــب وانتهــى التقريــر إلــى مــا يلــي ‪:‬ونــرى أن وفــاة املذكــور حدثــت‬\n‫بصــورة أساســية نتيجــة إصابتــه الطعنيــة بالفخــذ األميــن ومــا نتــج عنهــا‬\n‫مــن متزقــات باألوعيــة الدمويــة الرئيســية املــارة بأنســجة الفخــذ األميــن‬\n‫ومــا صاحــب ذلــك مــن نزيــف دمــوي غزيــر وأدى إلــى حــدوث صدمــة‬\n‫نزيفيــة غيــر مرجتعــة نتــج عنهــا وفاتــه ‪...‬الــخ ونــرى أن موقــع تعرضــه‬\n‫لإلصابــة الطعنيــة بالفخــذ األميــن والتــي أودت بحياتــه كان داخــل‬\n‫ســيارته ومــن احملتمــل أن تكــون مــن راكــب كان يركــب الســيارة‬\n‫بجــواره وذلــك حكمــا علــى موضــع إصابتــه بالفخــذ األميــن وكــذا مــن‬\n‫النزيــف الدمــوي املشــاهد بالســيارة أ‪-‬ه ـ ثالث ـاً‪ :‬وجدنــا بهــا علــى اللفــة‬\n‫(‪ )299‬مــن الدوســية رقــم (‪ )2‬علــى صفحــات التحقيــق (‪ )19-18‬أقــوال‬\n‫املدعــى عليــه املتضمنــة وجــود خــاف بينــه وبــن املجنــي عليــه بســبب‬\n‫قيــام املجنــي عليــه بالقــول لوالــد أخ املجنــي عليــه مــن أمــه املدعــو‪/‬‬\n‫‪......................‬أنهمــا لــم يحضــرا مناســبة العشــاء التــي كانــت لــدى أهــل‬\n‫‪...........‬ألنهمــا كانــا يف حالــة ســكر رابع ـ ًا وجدنــا بهــا علــى صفحــة‬\n‫رقــم (‪ 5‬ــ‪ )11‬مــن دفتــر التحقيــق لفــة رقــم (‪ )97‬مــن الدوســية رقــم (‪)5‬‬\n‫مــا يــدل علــى وجــود خــاف بــن املدعــى عليــه وزوجتــه بســبب قيــام‬\n‫املجنــي عليــه باالتصــال علــى زوجــة املدعــى عليــه يف الليلــة التــي تســبق‬\n\n\n                                                                                         ‫‪144‬‬\n\f      ‫مقتلــه وقيــام املدعــى عليــه ببيــع جــوال زوجتــه وضربــه لهــا ليلــة مقتــل‬\n      ‫املجنــي عليــه بســاعات خامسـ ًا وجدنــا بهــا علــى ملــف التحقيــق رقــم (‪)4‬‬\n      ‫لفــة (‪ 114‬حتــى ‪ )121‬تقريــر البحــث والتحــري الصــادر مــن شــرطة‬\n      ‫محافظــة خميــس مشــيط رقــم (‪ )...........‬يف ‪1430/9/15‬هـ ـ وقد تضمن‬\n      ‫التقريــر مــا يلــي ‪ :‬ســيرة املقتــول ‪........... /‬ســعودي اجلنســية يبلــغ مــن‬\n      ‫العمــر ‪ 35‬عــام متــزوج ولــه أبنــاء ويســكن حــي ‪...........‬ويعمــل برتبــة‬\n      ‫جنــدي بالدفــاع املدنــي مبدينــة ابهــا يفيــد التحــري بأنــه كان قبل زواجه‬\n      ‫رجــل متديــن مــن األشــخاص املشــهود لــه باالســتقامة وبعــد زواجــه بــدأت‬\n      ‫تظهــر عليــه عالمــات االنحــراف حيــث انــه بــدأ يدخــل يف مجــال تعاطــي‬\n      ‫املخــدرات وشــرب املســكر وكانــت النتيجــة مــن جــراء ذلــك تظهــر‬\n      ‫علــى ســلوكه حتــى أصبــح كثيــر املشــاكل والشــجار مــع مــن حولــه‬\n      ‫وهــو ســيء التعامــل مــع اآلخريــن ويرغــب يف إثــارة املشــاكل حتــى مــع‬\n      ‫أصدقائــه وأقاربــه ‪ ...‬توفــر للتحريــات معلومــات بأنــه مــروج للمخــدرات‬\n      ‫ويتعامــل مــع أشــخاص مــن ذلــك املجــال ‪ ...‬تشــير املعلومــات إلــى أن‬\n      ‫املقتول هو من يؤمن أصدقائه باملخدرات أمثال‪........... /‬و‪...........‬و‪...........‬‬\n      ‫ويحصلــون عليهــا عــن طريقــه ‪ ...‬توفــر معلومــات بــأن املقتــول لــه عالقــات‬\n      ‫مــع نســاء وبينــه وبينهــم دائمــا اتصــاالت واملعلومــات تشــير بــان‬\n      ‫‪...........‬و‪ ...........‬و‪ ...........‬يعرفــون عــن ذلــك جيــدا‪ ...‬كمــا توفــر لنــا‬\n      ‫معلومــات تفيــد بــأن املقتــول قبــل وفاتــه بيومــن قــد اتصــل علــى‬\n      ‫املدعــو‪.........../‬زوج والدتــه وذكــر لــه بــأن ابنــه املدعو‪.........../‬وهــو‬\n      ‫شــقيقه مــن أمــه وكذلــك املدعو‪.........../‬بأنهــم لــم يحضــروا أحــد‬\n      ‫املناســبات وهــو مــا أثــار الزعــل يف صــدر ‪...........‬و‪...........‬وقــد أتصــل‬\n      ‫عليــه ثابــت وقــال لــه بالنــص (ســود اهلل وجهــك)‪ ...‬مــن خــال التحريــات‬\n\n\n‫‪145‬‬\n\f‫فإنهــا تبــن بــأن ‪ ...........‬علــى عالقــة كبيــرة مــع املقتــول وأنهمــا أصدقاء‬\n‫صداقــة حميمــة ودائمـ ًا مــع بعضهمــا وكآل منهمــا يعــرف أســرار اآلخــر‬\n‫وال يخفيــا علــى بعضهمــا أي شــيء و دائمــا يحــدث بينهمــا مشــاجرات‬\n‫وخــاف الســيما إذا كانــوا بحالــة غيــر طبيعيــة كونهــم دائمــا يتعاطون‬\n‫املســكر ســويا ‪.‬كمــا أن املعلومــات تؤكــد بــأن أي جرميــة قــد يرغــب‬\n‫يف تنفيذهــا أحدهمــا فانــه ال يســتغني عــن االخــر يف مســاعدته لــه ‪...‬‬\n‫أ‪ -‬ه ـ سادسـاً‪ :‬وجدنــا بهــا علــى صفحــة رقــم (‪ 5‬ــ‪ )11‬مــن دفتــر التحقيــق‬\n‫لفــة رقــم (‪ )97‬مــن الدوســية رقــم (‪ )5‬أقــوال املدعــى عليــه وأقــوال زوجته‬\n‫مــن أنهــا هــي مــن قامــت بفتــح بــاب املنــزل لــه عنــد عودتــه وهــذا يــدل‬\n‫علــى أن املفاتيــح التــي وجــدت علــى طبلــون ســيارة املجنــي عليــه أمــام‬\n‫مقعــد الراكــب تعــود لــه ســابع ًا وجدنــا بهــا علــى صفحــة رقــم (‪ 9‬ــ‪)12‬‬\n‫مــن دفتــر التحقيــق لفــة رقــم (‪ )98‬مــن الدوســية رقــم (‪ )5‬مــا يــدل علــى‬\n‫هروبــه مــن منزلــه عنــد حضــور رجــال األمــن للقبــض عليــه واختبائــه يف‬\n‫الــوادي أكثــر مــن أربــع ســاعات وذكــر أن ســبب هروبــه خوف ـ ًا مــن‬\n‫املخــدرات التــي معــه ثامن ـ ًا ‪:‬وجدنــا بهــا تقريــر الطــب الشــرعي رقــم‬\n‫‪)...........‬بتاريــخ ‪1429/10/4‬ه ـ املشــار إليــه أعــاه و محضــر االنتقــال‬\n‫واملعاينــة الــذي تضمــن (أن املجنــي عليــه تعــرض للطعــن وهــو يف ســيارته‬\n‫خلــف املقــود مــن شــخص يف املقعــد املجــاور للســائق) ممــا يــدل علــى أن‬\n‫املجنــي عليــه يطمئــن ملــن كان معــه وهــذا يتفــق مــع مــا ورد بأقــوال‬\n‫املدعــى عليــه أنــه أكثــر شــخص قرب ـ ًا لــه وركوب ـ ًا معــه باســتمرار‬\n‫املرفــق لفــة رقــم (‪ 105‬ــ‪ )110‬مــن الدوســية رقــم (‪ )2‬وكذلــك املــدون‬\n‫علــى صفحــة رقــم (‪ 2‬ــ‪ )5‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ )2‬مــن‬\n‫الدوســية رقــم (‪ )2‬تاســع ًا ‪:‬وجدنــا بهــا علــى لفــة رقــم (‪ )52‬مــن الدوســية‬\n\n\n                                                                                       ‫‪146‬‬\n\f      ‫رقــم (‪ )5‬مكاملــة مســجلة بــن املدعــى عليــه وزوجتــه وفيهــا حتريــض‬\n      ‫علــى عــدم تغييــر أقوالهــا الســابقة والثبــات عليهــا عنــد قيــام اللجنــة‬\n      ‫بالتحقيــق معهــا عاشــر ًا ‪:‬وجدنــا بهــا علــى لفــة رقــم (‪ )282‬مــن الدوســية‬\n      ‫رقــم (‪ )4‬احملضــر املعــد مــن احملقــق يف هيئــة التحقيــق واالدعــاء العــام‬\n      ‫واملتضمــن قيــام املدعــى عليــه بالهــروب مــن مقــر فــرع الهيئــة مبنطقــة‬\n      ‫عســير وعــدم حضــوره إال بعــد القبــض عليــه حــادي عشــر ‪:‬وجدنــا بهــا‬\n      ‫علــى صفحــة رقــم (‪ )11‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪ )129‬مــن‬\n      ‫الدوســية رقــم (‪ )4‬إقــرار املدعــى عليــه مــؤرخ يف ‪1431/3/22‬ه ـ بأنــه‬\n      ‫هــرب مــن مبنــى هيئــة التحقيــق وســلم نفســه بعــد يومــن مــن هروبــه أ ‪،‬‬\n      ‫ه ـ وبعــرض مــا مت تدوينــه أعــاه علــى املدعــى عليــه احلاضــر أجــاب بقوله‬\n      ‫إننــي علــى كالمــي الســابق فلــم أقتــل مــورث هــذا احلاضــر وال أعلــم مــن‬\n      ‫قتلــه وبالنســبة لهربــي مــن البيــت فهــو بســبب املخــدرات وبســؤال املدعــي‬\n      ‫أصالــة ووكالــة هــل لديــه مزيــد بينــة فقــال ليــس لــدي ســوى مــا مت‬\n      ‫رصــده ونظــر ًا لضيــق الوقــت فقــد مت رفــع اجللســة للتأمــل إلــى يــوم‬\n      ‫األربعــاء ‪1433/6/18‬ه ـ وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد حــرر بتاريــخ ‪1433/6/17‬ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم‬\n      ‫األربعــاء املوافق‪1433/6/18‬ه ـ الســاعة احلاديــة عشــر صباح ـ ًا فتحــت‬\n      ‫اجللســة لدينــا نحــن قضــاة املشــترك يف احملكمــة العامــة بخميــس‬\n      ‫مشــيط ‪ ...........‬و‪...........‬و‪...........‬وحيــث جــرت دراســة القضيــة وتأملهــا‬\n      ‫ودراســة كافــة متعلقاتهــا فلــم جنــد بهــا قرائــن توجــد غلبــة الظــن بــأن‬\n      ‫املدعــى عليــه هــو القاتــل للمجنــي عليــه وال ينبغــي أن يحلــف املدعــي‬\n      ‫للقتــل إال بعــد االســتثبات وغلبـ ُة ظـ ٍـن تقــارب اليقــن ولــم جنــد شــيئا مــن‬\n      ‫ذلــك فاملدعــي عليــه لــم يشــاهد مــع املجنــي عليــه وليــس هنــاك عــداوة‬\n\n\n‫‪147‬‬\n\f‫توجــب القتــل بــل األمــر علــى العكــس مــن ذلــك فهنــاك عالقــة حميميــة‬\n‫بينهمــا بحســب مــا ورد يف تقريــر البحــث والتحــري املرصــودة أعــاه وال‬\n‫يوجــد أي تقاريــر أو بصمــات تديــن املدعــى عليــه ومــا ذكــره املدعــي‬\n‫أصالــة ووكالــة مــن أن املفاتيــح املوجــودة علــى الطبلــون تعــود للمدعــى‬\n‫عليــه ال يوجــد باملعاملــة مــا يــدل عليــه مــع أن التأكــد مــن ذلــك أمــر متاح‬\n‫ويســير ولــم جنــد يف أوراق املعاملــة مــا يــدل علــى أن هــذه املفاتيــح تخــص‬\n‫املدعــى عليــه وأمــا مــا ذكــر يف الفقــرة رابع ـ ًا مــن وجــود خــاف بــن‬\n‫املدعــى عليــه وزوجتــه بســبب قيــام املجنــي عليــه باالتصــال علــى جــوال‬\n‫زوجــة املدعــى عليــه فلــم جنــد إقــرارا صريحـ ًا مــن املدعــى عليــه وزوجتــه‬\n‫بذلــك وهــذا األمــر مجــرد احتمــال كمــا أن ورود اتصــال مــن جــوال‬\n‫املجنــي عليــه جلــوال زوجــة املدعــى عليــه أمــر غيــر مســتغرب كــون‬\n‫بينهمــا عالقــة وصداقــة كبيــرة ومبراجعتــه مــا ذكــر أهــل العلــم فيمــا‬\n‫يتعلــق باللــوث وجــد أن املــراد بــه العــداوة الظاهــرة وميثــل لــه الفقهــاء بعــدة‬\n‫أمثلــة منهــا ‪ :‬الثــأر بــن القبائــل او الشــرط واللصــوص او تفــرق جماعــة‬\n‫عــن قتيــل او أن يزدحــم النــاس يف مضيــق فيوجــد فيهــم قتيــل أو أن‬\n‫يوجــد قتيــل بقربــه رجــل معــه ســيف ملطــخ بــدم او ان تقتتــل فئتــان‬\n‫فيفرقــون عــن قتيــل مــن احدهمــا فاللــوث علــى األخــرى او أن تشــهد بينـ ٌة‬\n‫ناقصــة مثــل شــهادة رجــل واحــد أو شــهادة النســاء أو الصبيــان أو تقــوم‬\n‫البينــة علــى وجــود العــداوة أو أن يقــول املقتــول قبــل قتلــه قتلنــي فــان‬\n‫ويوجــد بــه جــرح ولــم جنــد يف هــذه الدعــوى شــيئا مــن ذلــك وال مــا ميكــن‬\n‫أن يقــاس عليــه ‪ .‬جــاء يف الكشــاف (‪« )13/470‬ومتــى ادعــى أحــد‬\n‫القتــل عمــد ًا أو غيــره مــع عــدم اللــوث أو وجــد قتيــل يف موضــع فادعــى‬\n‫أوليــاءه علــى قاتــل مــع عــدم اللــوث حلــف املدعــى عليــه ميينــا واحــده‬\n\n\n                                                                                            ‫‪148‬‬\n\f      ‫وبــرئ» أ‪ -‬ه ـ وجــاء يف املغنــي (‪»)12/189‬إذا وجــد قتيــل يف موضــع ‪،‬‬\n      ‫فادعــى أوليــاؤه قتلــه علــى رجــل أو جماعــة ولــم تكــن بينهــم عــداوة وال‬\n      ‫لــوث فهــي كســائر الدعــاوى إن كانــت لهــم بينــة حكــم لهــم بهــا وإال‬\n      ‫فالقــول قــول املنكــر وبهــذا قــال مالــك والشــافعي وابــن املنــذر « أ‪-‬ه ـ‬\n      ‫وقــال يف موضــع آخــر (‪« )12/191‬واليمــن واحــده ألنــه يعضدهــا‬\n      ‫الظاهــر واألصــل فلــم تغلــظ وعــن احمــد يشــرع خمســون ميينــا ألنهــا‬\n      ‫دعــوى يف القتــل فــكان املشــروع فيهــا خمســون ميينــا كمــا لــو كان‬\n      ‫بينهــم لــوث وللشــافعي قــوالن علــى ذلــك» أ‪-‬ه ـ فبنــاء علــى مــا تقــدم فقــد‬\n      ‫اســتبان لنــا ضعــف بينــة املدعــى أصالــة ووكالــة ‪.‬وألن األصــل عصمــت‬\n      ‫دم املســلم فــا يســتباح اال ببينــة واضحــة وصريحــة لــذا فقــد افهمنــا‬\n      ‫املدعــي أصالــة ووكالــة بــأن لــه ميــن املدعــى عليــه وقررنــا تغليــظ اليمني‬\n      ‫عليــه بنــاءا علــى مــا اشــرنا أعــاه حســب مــا جــاء الروايــة الثانيــة عــن‬\n      ‫احمــد وهــو احــد قولــي الشــافعي وجعلنهــا خمســون ميينــا ولفظهــا (واهلل‬\n      ‫العظيــم مــا قتلــت ‪...........‬وال شــاركت يف قتلــه وال أحدثــت شــيئ ًا مــات‬\n      ‫منــه وال كنــت ســببا يف موتــه وال كنــت معينــا علــى موتــه) وبعــرض‬\n      ‫ذلــك علــى املدعــي أصالــة ووكالــة قــال ال اقبــل ميــن هــذا احلاضــر وقــال‬\n      ‫اطلــب أميــان كافــة أســرته هكــذا أجــاب وأجــاب املدعــى عليــه إننــي‬\n      ‫مســتعد بــأداء خمســن ميــن علــى الصفــة املذكــورة شــرعا متــى طلبــت‬\n      ‫منــي فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه‬\n      ‫قيامــه بقتــل مــورث املدعــن ومبــا أن املدعــي باحلــق اخلــاص ال بينة موصلة‬\n      ‫لــه علــى دعــواه ومبــا أن اليمــن توجهــت علــى املدعــى عليــه واســتعد‬\n      ‫بأدائهــا ولعــدم قبــول املدعــي أصالــة ووكالــة ميــن املدعــى عليــه لــذا‬\n      ‫فقــد قررنــا مــا يلــي‪ :‬أو ًال ‪:‬لــم يثبــت لدينــا إدانــة املدعــى عليــه بقتــل‪/‬‬\n\n\n‫‪149‬‬\n\f‫‪...........‬ثانيــا‪ :‬صرفنــا النظــر عــن طلــب املدعــي أصالــة ووكالــة لعــدم‬\n‫ثبــوت موجبــه ثالثــا‪ :‬أفهمنــا املدعــي أصالــة ووكالــة بــأن لــه ميــن املدعــى‬\n‫عليــه متــى طلبهــا ولــه املطالبــة بالديــة يف مواجهــة بيــت املــال بعــد‬\n‫االســتئذان مــن املقــام الســامي وبذلــك حكمنــا وبعرضــه علــى املدعــى‬\n‫أصالــة ووكالــة لــم يقتنــع وطلــب رفعهــا حملكمــة االســتئناف ووعــد‬\n‫بتقــدمي الئحــة اعتراضيــة فأجيــب لطلبــه وجــرى تزويــده هــذا اليــوم‬\n‫بنســخة مــن صــك احلكــم لالعتــراض عليــه خــال ثالثــن يومــا مــن‬\n‫تاريخــه وإذا لــم يتقــدم باعتراضــه خــال املــدة احملــددة نظامــا فســيرفع‬\n‫احلكــم حملكمــة االســتئناف بــدون الئحــة أمــا املدعــى عليــه فقــد قنــع‬\n‫بذلــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه أجمعــن حــرر بتاريــخ ‪1433/6/18‬ه ـ احلمــد هلل وحــده وبعــد‬\n‫ففــي يــوم االثنــن املوافــق ‪1434/8/22‬ه ـ فتحــت اجللســة لدينــا نحــن‬\n‫قضــاة املشــترك‪...........‬و ‪...........‬و‪ ...........‬وقــد عــادت املعاملــة بعــد رفعهــا‬\n‫حملكمــة االســتئناف ب ــعسير برفــق خطــاب فضيلــة رئيــس محكمــة‬\n‫االســتئناف مبنطقــة عســير برقــم وتاريــخ ‪1433/10/11‬ه ـ املرفــق بــه‬\n‫قــرار الدائــرة اخلماســية األولــى برقــم وتاريــخ ‪1433/8/25‬ه ـ ونــص‬\n‫احلاجــة منــه وبدراســة القــرار الشــرعي وصورتــه وضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة لوحــظ مــا يلــي ‪:‬أوالً‪ /‬أن دعــوى املدعــي‬\n‫أصالــة ووكالــة غيــر محــررة واملنصــوص عليــه أن الدعــوى ال تقبــل إال‬\n‫محــررة حتريــر ًا يعلــم بــه املدعــي فالبــد مــن حتريرهــا حتــى يكــون‬\n‫احلكــم مالقيــا للدعــوى واإلجابــة‪ .‬ثانيـاً‪ /‬يوجــد مبذكــرة االعتــراض‬\n‫مــا يوجــب مناقشــته فالبــد مــن إعــادة االطــاع عليهــا ومناقشــة ذلــك مــع‬\n‫طــريف النــزاع ‪ .‬ثالثـاً‪ /‬لــو يــرى أصحــاب الفضيلــة إعــادة النظــر للتحقيــق‬\n\n\n                                                                                             ‫‪150‬‬\n\f      ‫مــع املدعــى عليــه ومــع زوجتــه حيــث يوجــد بعــض القرائــن القويــة مثــل‬\n      ‫موضــوع املفتــاح واالتصــاالت الهاتفيــة والقضيــة علــى جانــب مــن األهمية‬\n      ‫فعلــى أصحــاب الفضيلــة مالحظــة مــا ذكــر وإحلــاق مــا يجرونــه يف‬\n      ‫الضبــط وصورتــه والصــك الشــرعي وســجله ومــن ثــم إعــادة املعاملــة‬\n      ‫إلكمــال الزمهــا واهلل املوفــق قاضــي اســتئناف ‪...........‬مجــاز وموقــع‬\n      ‫علــى األصــل قاضــي اســتئناف ‪...........‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫‪......................‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...........‬ختمــه وتوقيعــه‬\n      ‫رئيــس الدائــرة ‪...........‬ختمــه وتوقيعــه أ‪ -‬ه ـ وحيــث جــرى إعــادة املعاملــة‬\n      ‫مــن قبــل القائــم بالعمــل يف املكتــب القضائــي الثامــن بطلــب التوجيــه‬\n      ‫حيــال نــدب الشــيخ ‪...........‬فوردنــا قــرار الدائــرة قــرار الدائــرة اخلماســية‬\n      ‫األولــى برقــم ‪ 33472983‬وتاريــخ ‪1433/12/19‬ه ـ ونــص احلاجــة منــه‬\n      ‫أن مــادام فضيلــة القاضــي املشــارك منتــدب مبحكمــة الريــاض‬\n      ‫فيكمــل الــازم أو ًال مــن قبــل فضيلــة القاضيــن اللذيــن علــى رأس‬\n      ‫العمــل ثــم بعــث األوراق مبــا فيهــا احلكــم لفضيلــة القاضــي املشــارك يف‬\n      ‫مقــر عملــه اآلن التخــاذ مــا يلــزم فعلــى أصحــاب الفضيلــة مالحظــة مــا‬\n      ‫ذكــر وإحلــاق مــا يجرونــه يف الضبــط وصورتــه والصــك وســجله ومــن ثــم‬\n      ‫تعــاد املعاملــة إلكمــال الزمهــا واهلل املوفــق قاضــي اســتئناف ‪...........‬‬\n      ‫منتــدب وموقــع علــى األصــل قاضــي اســتئناف ‪...........‬ختمــه وتوقيعــه‬\n      ‫قاضــي اســتئناف ‪...........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...........‬ختمــه‬\n      ‫وتوقيعــه رئيــس الدائــرة ‪...........‬ختمــه وتوقيعــه أ‪ -‬ه ـ ونظــر ًا النتهــاء ندب‬\n      ‫القاضــي ‪...........‬لــذا فقــد فتحــت اجللســة هــذا اليــوم وحضــر املدعــي‬\n      ‫باحلــق اخلــاص أصالــة ووكالــة كمــا حضــر املدعــى عليــه وبطلــب حترير‬\n      ‫الدعــوى مــن املدعــي أصالــة ووكالــة قــال إنــه بتاريــخ ‪1429/8/28‬هـ ـ‬\n\n\n‫‪151‬‬\n\f‫ـاء وأثنــاء وجــود املدعــى عليــه مــع‬ ‫مــن يــوم اخلميــس الســاعة ‪ 10.30 :‬مسـ ً‬\n‫مورثــي يف وادي ‪...........‬شــرق حــي ‪...........‬مبحافظــة خميــس مشــيط‬\n‫وهــو راكــب الــى جــواره يف ســيارة مورثــي مــن نــوع ‪ ........‬انتــاج ‪........‬‬\n‫أقــدم املدعــى عليــه هــذا احلاضــر ‪...........‬علــى قتــل مورثــي ومــورث‬\n‫موكلــي وذلــك بطعنــة بــأداة حــادة يف فخــذه األميــن أدت إلــى إحــداث‬\n‫متزقــات باألوعيــة الدمويــة ونزيــف دمــوي غزيــر ممــا نتــج عنهــا وفاتــه‬\n‫حيــث لــم يقــم املدعــى عليــه بإســعافه أو تبليــغ اجلهــات األمنيــة لــذا فإنــي‬\n‫أتهــم هــذا احلاضــر بالقيــام بقتــل مورثــي ومــورث موكلــي وذلــك بطعنــة‬\n‫بــأداة حــادة يف فخــذه األميــن أدت إلــى إحــداث متزقــات باألوعيــة الدمويــة‬\n‫ونزيــف دمــوي غزيــر ممــا نتــج عنهــا وفاتــه حيــث لــم يقــم املدعــى عليــه‬\n‫بإســعافه أو تبليــغ اجلهــات األمنيــة لــذا فإنــي أتهــم هــذا احلاضــر بالقيــام‬\n‫بقتــل مورثــي ومــورث موكلــي عمــد ًا عدوان ـ ًا أطلــب قتــل هــذا احلاضــر‬\n‫قصاصــا لقــاء قتلــه مورثــي ومــورث موكلــي هــذه دعــواي وبعــد ذلــك‬\n‫جــرى عــرض الدعــوى علــى املدعــى عليــه احلاضــر فقــال ليــس لــدي مزيــد‬\n‫علــى مــا ذكرتــه يف اجللســة الســابقة فمــا ذكــره املدعــي غيــر صحيــح‬\n‫ا هكــذا أجــاب ثــم جــرى االطــاع علــى الالئحــة‬              ‫جملــة وتفصي ـ ً‬\n‫االعتراضيــة املقدمــة مــن املدعــي أصالــة ووكالــة وممــا تضمنتــه وجــود‬\n‫مفاتيــح منــزل املدعــى عليــه علــى طبلــون الســيارة فجــرى ســؤال املدعــى‬\n‫عليــه عــن ذلــك فأجــاب هــذه املفاتيــح ال تخصنــي ومفاتيحــي كانــت‬\n‫بالبيــت ثــم جــرى ســؤاله عمــا ذكــر مــن وجــود خــاف بينــه وبــن املجنــي‬\n‫عليــه حســب اعترافــه فأجــاب صحيــح أنــه كان بينــي وبــن مــورث هــذا‬\n‫احلاضــر مشــاجرة بســبب أنــه اتهمنــي يف مجلــس عمــه زوج أمــه بأننــي‬\n‫أشــرب اخلمــر أنــا و‪ ...........‬شــقيقه فقــط ثــم جــرى ســؤاله عــن ســبب‬\n\n\n                                                                                        ‫‪152‬‬\n\f      ‫هروبــه مــن هيئــة التحقيــق واالدعــاء العــام فأجــاب إننــي هربــت بســبب‬\n      ‫أنــه كان بحوزتــي مخــدرات (‪ )72‬حبــة فخفــت أن يعثــروا عليهــا معــي‬\n      ‫وقمــت بالتخلــص منهــا وكنــا قــد كتبنــا إلــى هيئــة التحقيــق واالدعــاء‬\n      ‫العــام بخطابنــا رقــم ‪ 34118227‬وتاريــخ ‪1434/3/1‬ه ـ بإعــادة التحقيــق‬\n      ‫يف القضيــة فيمــا يتعلــق باملفتــاح واملكاملــات الهاتفيــة فوردنــا اجلــواب‬\n      ‫باخلطــاب رقــم ‪...........‬وتاريــخ ‪1434/5/6‬ه ـ واملتضمــن إعــادة التحقيــق‬\n      ‫مــع املتهــم وزوجتــه وباالطــاع علــى مــا ورد مبلــف التحقيــق لــم جنــد بــه‬\n      ‫مزيــد ًا علــى مــا ذكــر يف املعاملــة األساســية لــذا فلــم يظهــر لنــا خــاف‬\n      ‫مــا أجرينــاه ونســأل اهلل لنــا وللمشــايخ الســداد يف القــول والعمــل وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آله وصحبــه أجمعني‬\n      ‫حــرر بتاريــخ ‪1434/8/22‬ه ـ ‪ ،‬احلمــد هلل وحــده وبعــد فلــدي أنــا‪...........‬‬\n      ‫القاضــي يف احملكمــة العامــة بخميــس مشــيط وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بخميــس مشــيط‬\n      ‫املكلف برقم ‪ 33410367‬وتاريخ ‪ 1433/06/17‬هـ املقيدة باحملكمة‬\n      ‫برقــم ‪ 331146056‬وتاريــخ ‪ 1433/06/17‬ه ـ ففــي يــوم االثنــن‬\n      ‫املوافــق‪ 1434/12/16‬ه ـ افتتحــت اجللســة الســاعة العاشــرة والربــع وقــد‬\n      ‫وردنــا خطــاب فضيلــة رئيــس محكمــة االســتئناف مبنطقــة عســير برقم‬\n      ‫‪ 342343614‬يف ‪1434/11/11‬ه ـ املرفــق بــه قــرار الدائــرة اخلماســية‬\n      ‫األولــى برقــم ‪ 34338103‬وتاريــخ ‪1434/10/22‬ه ـ واملتضمــن املوافقــة‬\n      ‫علــى احلكــم ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/12/16‬ه ـ احلمــد هلل وحــده وبعــد فقــد‬\n      ‫اطلعنــا نحــن قضــاة الدائرة األولى لتدقيق القضايا اخلماســية مبحكمة‬\n      ‫االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n\n\n‫‪153‬‬\n\f‫احملكمــة العامــة بخميــس مشــيط برقــم ‪ 341632638‬وتاريــخ‬\n‫‪1434/10/11‬ه ـ املرفــق بهــا الصــك الشــرعي الصــادر مــن أصحــاب‬\n‫الفضيلــة القضــاة باحملكمة الشــيخ‪........... /‬والشــيخ‪........... /‬والشــيخ‪/‬‬\n‫‪...........‬املســجل برقــم ‪ 33306057‬وتاريــخ ‪1433/6/18‬ه ـ اخلــاص‬\n‫بدعوى ‪ ...........‬أصالة عن نفسه وبوكالته عن ورثة ابنه ‪......................‬‬\n‫ضـ ــد‪ (........... /‬ســعودي اجلنســية) التهامــه يف قضيــة (قتــل) علــى الصفــة‬\n‫املوضحــة يف الصــك املتضمــن حكــم أصحــاب الفضيلــة مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وحيــث ســبق دراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة ‪ ،‬وباالطــاع علــى مــا أجــاب بــه أصحــاب‬\n‫ـاء علــى قرارنــا رقــم‬     ‫الفضيلــة وأحلقــوه بال ــصك وصــورة ضبطــه بنـ ً‬\n‫‪ 33391336‬وتاريــخ ‪1433/8/25‬ه ـ ـ وقرارنــا رقــم ‪ 33472983‬وتاريــخ‬\n‫‪ 1433 / 12 / 19‬ه ـ ـ تقــررت املوافقــة علــى احلكــم بعــد االجــراء األخير‬\n    ‫‪ ،‬واهلل املوفق و صلى اهلل على نبينا محمد وعلى آله وصحبه وسلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪154‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":136,"source_page_end":154,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"95f6aa5795ecd7e316cca559bec6da53b431417634ba785a08387039ad2a4146","normalized_text_hash":"935e39e98114613407f003e0700bcd9ef1b08db9b943c6136cebb2423e5b79ba","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p136-33306057"},{"id":"2c1138a7-7f1e-5c6a-b294-70cd08fb7230","document_type":"judgment","category":"judicial","subcategory":"general","title":"قتل خطأ -تعديل المحكمة للوصف اجلرمي -انتفاء نية القصد اجلنائي -تعزير قاتل اخلطأ -تنازل عن حق خاص -تعزير بالسجن واجللد .","document_number":"34186165","case_number":"34111287","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"قتل خطأ -تعديل المحكمة للوصف اجلرمي -انتفاء نية القصد اجلنائي -تعزير قاتل اخلطأ -تنازل عن حق خاص -تعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34186165 :‬تاريخه‪1434/4/13 :‬ه‬\n                         ‫رقم الدعوى‪34111287:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34215515‬تاريخه‪1434/5/19 :‬هـ‬\n\n\n      ‫قتــل خطــأ ‪ -‬تعديــل احملكمــة للوصــف اجلرمــي ‪-‬انتفــاء نيــة القصــد‬\n      ‫اجلنائــي ‪ -‬تعزيــر قاتــل اخلطــأ ‪ -‬تنــازل عــن حــق خــاص ‪ -‬تعزيــر‬\n                                                         ‫بالســجن واجللــد ‪.‬‬\n\n\n\n\n                                  ‫‪ -1‬املادة (‪ )159‬من نظام االجراءات اجلزائية‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بقتــل نفــس‬\n      ‫معصومــة « شــبه عمــد » وذلــك بصدمــه بســيارته والتســبب يف وفاتــه‬\n      ‫أثنــاء قيامــه مبمارســة التفحيــط واالســتهتار وعــدم املبــاالة بتعريــض‬\n      ‫حيــاة اآلخريــن للخطــر ‪ ،‬وطلــب إثبــات الوصــف اجلرمــي لــه واحلكــم‬\n      ‫عليــه مبــا قضــت بــه اإلرادة امللكيــة وتشــديد العقوبــة التعزيريــة عليــه‬\n      ‫حيــث كان املجنــي عليــه واقفــا يف وســط الســاحة يشــجعه ملــا كان‬\n      ‫املدعــى عليــه يقــوم بالتفحيــط فيهــا وكان الوقــت ليــا فلــم يشــاهده‬\n      ‫حتــى صدمــه فترجــل مــن ســيارته وأســعفه إال أن املنيــة أدركتــه ‪ ،‬أقــر‬\n      ‫املدعــى عليــه بصحــة دعــوى املدعــي العــام بأنــه كان مــع مجموعــة مــن‬\n      ‫األشــخاص ومنهــم املجنــي عليــه املقتــول يشــاهدون مســيرات االحتفــال‬\n      ‫باليــوم الوطنــي توجهــوا إلــى حــي آخر فوردتهم رســالة علــى جواله بوجود‬\n\n‫‪155‬‬\n\f‫تفحيــط بالســيارات يف ســاحة ونــزل الذيــن معــه لــدى الســاحة ملشــاهدة‬\n‫التفحيــط وملــا فرغــوا ركــب معــه بعــض األشــخاص عائديــن لعرعــر‬\n‫إال أن الشــيطان ســول لــه بــأن يعــود إلــى الســاحة ملمارســة التفحيــط‬\n‫بســيارته وملــا كان يفحــط بهــا بســرعة (‪ 100‬كــم ‪ /‬الســاعة ) كان‬\n‫املجنــي عليــه واقفــا ضمــن املتجمهريــن يف وســط الســاحة وكانــت‬\n‫مظلمــة فلــم يتمكــن مــن رؤيتــه إال عندمــا اقتــرب منــه فحــاول االبتعــاد‬\n‫عنــه ولكــن لــم يتمكــن مــن الســيطرة علــى الســيارة فتوقــف ونــزل مــن‬\n‫الســيارة وقامــا بإســعافه إلــى املستشــفى ثــم تــويف الحقــا علــى إثــر احلادث‬\n‫ولــم يكــن لــه قصــد جنائــي يف قتلــه ‪ ،‬جــرى االطــاع علــى تقريــر املــرور‬\n‫املتضمــن اإلشــارة لوقائــع احلــادث تركيــز اإلدانــة علــى املدعــى عليــه‬\n‫بنســبة (‪ )%50‬مــن مســؤولية احلــادث إلعترافــه مبمارســة التفحيــط ‪،‬‬\n‫بينمــا بقيــة النســبة علــى املجنــي عليــه املتوفــى لكــون محــل احلــادث يف‬\n‫منتصــف الســاحة وتبعــد عــن مــكان املتجمهريــن مســافة ال تقــل عــن‬\n‫عشــرين متــرا وملــا ورد يف شــهادة الشــهود بــأن املجنــي عليــه ( املتوفــى )‬\n‫كان يشــجع املفحطــن ولعــدم وجــود مــا يبــرر تواجــده يف الســاحة التــي‬\n‫كان ميــارس فيهــا التفحيــط يف الســاعة الثانيــة بعــد منتصــف الليــل يف‬\n‫منطقــة نائيــة ال يوجــد بهــا إنــارة ال ســيما وأنــه رجــل أمــن ويــدرك عواقــب‬\n‫مــا قــام بــه ‪ ،‬جــاء يف تقريــر املــرور اإلشــارة للمــواد النظاميــة املتعلقــة‬\n‫للقضيــة حيــث ورد فيــه مــا نصــه ‪« :‬املــواد النظاميــة ‪-:‬أو ًال ‪ /‬حتديــد‬\n‫املســئولية ‪-1-:‬تنطبــق املــادة (‪ ) 60‬مــن نظــام املــرور علــى الســائق‬\n‫ونصهــا (يعــد احلــادث موجب ـ ًا للمســئولية إذا نتــج مــن اإلهمــال ‪ ،‬أو قلــة‬\n‫االحتــراز‪ ،‬أو عــدم مراعــاة األنظمــة) ‪ .‬ثاني ـ ًا ‪ /‬العقوبــات ‪ -1‬تنطبــق‬\n‫املــادة (‪ )62‬مــن نظــام املــرور علــى الســائق ونصهــا ( كل مــن أتلــف نفــس‬\n\n\n                                                                                       ‫‪156‬‬\n\f      ‫ال أو بعضــا ‪ ،‬يف حــادث ســير متعديـ ًا ‪ ،‬أو مفرطـ ًا يعاقــب‬    ‫إنســان ‪ ،‬ك ً‬\n      ‫بالســجن مــدة ال تزيــد عــن ســنة واحــدة ‪ ،‬وبغرامــة ماليــة ال تزيــد عــن‬\n      ‫عشــرة آالف ريــال ‪ ،‬أو بإحــدى هاتــن العقوبتــن ‪ ،‬دون إخــال مبــا تقــرر‬\n      ‫للحــق اخلــاص) ‪ ،‬جــرى االطــاع علــى أقــوال الشــهود والتقاريــر الطبيــة‬\n      ‫فــإذا هــي موافقــة ملــا ذكــر ‪ ،‬عليــه وإلقــرار املدعــى عليــه ولعــدم وجــود‬\n      ‫مــا يشــير إلــى القصــد اجلنائــي وملــا ورد يف تقريــر املــرور والتقريــر الطبــي‬\n      ‫ولعــدم وجــود ســوابق علــى املدعــى عليــه وملــا جــاء يف املــادة (‪ )159‬مــن‬\n      ‫نظــام االجــراءات اجلزائيــة بــأن للمحكمــة تغييــر الوصــف اجلرمــي ‪،‬‬\n      ‫ونظــرا النتشــار التفحيــط وملــا يحتويــه مــن خطــورة بالغــة مــن إزهــاق‬\n      ‫ألرواح أبريــاء ‪ ،‬إضافــة ملــا يصاحبهــا مــن مقاصــد ومــآرب ‪ ،‬ولتنــازل‬\n      ‫أصحــاب احلــق اخلــاص ‪ ،‬فقــد قــررت احملكمــة بأنــه لــم يثبــت لديهــا‬\n      ‫إدانــة املدعــى عليــه بالقتــل «شــبه العمــد» ‪ ،‬لكــن ثبــت لديهــا إدانتــه‬\n      ‫بالتفحيــط ممــا تســبب معــه بقتــل نفــس معصومــة خطــأ وحكمــت عليــه‬\n      ‫بســجنه ثــاث ســنوات مــن تاريــخ إيقافــه وجلــده مئــة وخمســن جلــدة‬\n      ‫مفرقــة علــى خمــس دفعــات يف كل دفعــة ثالثــن جلــدة يفصــل بــن كل‬\n      ‫دفعــة والتــي تليهــا عشــرة أيــام ‪ ،‬بعــرض احلكــم علــى املدعــى عليــه قــرر‬\n      ‫القناعــة بينمــا قــرر املدعــي العــام عــدم القناعــة واســتعد بتقــدمي الئحــة‬\n      ‫فأفهــم بتعليمــات االســتئناف ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‬\n\n\n\n\n‫‪157‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة العامــة‬\n‫……… وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34111287‬وتاريــخ ‪ 1434/03/08‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34584651‬وتاريــخ ‪ 1434/03/08‬ه ـ ففــي يــوم‬\n‫الســبت املوافــق‪ 1434/04/13‬ه ـ افتتحــت اجللســة الســاعة ‪10 : 30‬‬\n‫ا ‪ :‬بصفتــي مدعيـ ًا عامـ ًا‬   ‫وفيهــا حضــر املدعــي العــام ‪...........‬وقــرر قائـ ً‬\n‫بدائــرة اإلدعــاء العــام لفــرع الهيئــة مبنطقــة احلــدود الشــمالية أدعــي‬\n‫‪ ...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...........‬فإنــه يف‬\n‫متــام الســاعة الثانيــة صباح ـ ًا مــن يــوم اجلمعــة املوافــق ‪1433/11/5‬ه ـ‬\n‫وأثنــاء قيــام املتهــم‪ 21(........... /‬عامـاً) مبمارســة التفحيــط بســيارة مــن‬\n‫نــوع جمــس حــوض لونهــا بنــي رقــم اللوحــة (‪ )...........‬غمــاره ونــص موديــل‬\n‫(‪ )2007‬تعــود ملكيتهــا لــ‪........... /‬علــى طريــق رفحــاء بســاحة جامعــة‬\n‫احلــدود الشــمالية قــام بصــدم املواطــن‪ 23(........... /‬عام ـاً) الــذي كان‬\n‫متواجــد ًا يف منتصــف الســاحة ملشــاهدة التفحيــط وكان يرافــق املتهــم‬\n‫كل مــن املواطــن‪ 19(........... /‬عام ـاً) ســجل مدنــي رقــم (‪، )...........‬‬\n‫واملواطــن‪ 19(........... /‬عام ـاً) ســجل مدنــي رقــم (‪ ، )...........‬وقــد مت‬\n‫توقيــف املتهــم وإيداعــه الســجن العــام لكــون القضيــة تعتبــر مــن‬\n‫اجلرائــم الكبيــرة املوجبــة للتوقيــف اســتناد ًا للفقــرة رقــم (‪ )2‬مــن القــرار‬\n‫الــوزاري رقــم (‪ . )1900‬وباســتجواب املتهــم‪ /‬أقــر وهــو بكامــل قــواه‬\n‫العقليــة املعتبــرة شــرع ًا مــن دون إجبــار وال إكــراه مــن أحــد مبــا نســب‬\n‫إليــه وذكــر أنــه يف يــوم اخلميــس املوافــق ‪1433/11/5-4‬ه ـ الســاعة‬\n\n                                                                                         ‫‪158‬‬\n\f      ‫التاســعة مســاء كان مــع مجموعــة أشــخاص ومنهــم املجنــي عليــه ‪/‬‬\n      ‫‪ ،...........‬يف شــارع ‪...........‬يشــاهدون مســيرات االحتفــال ثــم ذهبــوا إلــى‬\n      ‫حــي ‪...........‬وتوقفــوا عنــد فنــادق ‪...........‬ثــم جــاءت رســالة علــى جــوال‬\n      ‫املتهــم عــن طريــق برنامــج البــاك بيــري كان نصهــا (توجيــه تفحيــط‬\n      ‫بســاحة اجلامعــة ‪ .....‬الــخ) ثــم ذهبــوا إلــى ســاحة اجلامعــة بســيارته مــن‬\n      ‫نــوع جمــس حــوض لونهــا بنــي رقــم اللوحــة (‪ )...........‬غمــاره ونــص موديــل‬\n      ‫(‪ )2007‬وكان معــه بالســيارة شــخص يدعــى ‪...........‬وشــخص اســمه‬\n      ‫‪...........‬و‪...........‬وذهبــوا إلــى ســاحة اجلامعــة ونــزل األشــخاص الذيــن‬\n      ‫كانــوا معــه بالســاحة ملشــاهدة التفحيــط وعندمــا انتهــى التفحيــط‬\n      ‫ركــب مــع املتهــم ‪...........‬و‪...........‬وذهبــوا يريــدون الرجــوع إلــى عرعــر‬\n      ‫ولكــن إبليــس سـ ّـول لــه العــودة إلــى ســاحة التفحيــط ملمارســة التفحيــط‬\n      ‫وعندمــا كان يفحــط بالســيارة كان يســير بســرعة ‪100‬كــم ‪/‬‬\n      ‫الســاعة) وكان املجنــي عليــه ‪........... /‬واقفـ ًا بوســط الســاحة وكانــت‬\n      ‫الســاحة مظلمــة ولــم يتمكــن املتهــم مــن رؤيتــه إال عندمــا اقتــرب منــه‬\n      ‫فحــاول االبتعــاد عنــه ولكــن لــم يتمكــن مــن الســيطرة علــى الســيارة‬\n      ‫وحــاول املجنــي عليــه الهــروب مــن أمــام الســيارة ولــم يســتطع فصدمــه‬\n      ‫املتهــم فســقط علــى األرض علــى بعــد مســافة مــن الســيارة فتوقــف املتهــم‬\n      ‫ونــزل مــن الســيارة وقــام بإســعاف املجنــي عليــه إلــى مستشــفى األميــر‬\n      ‫……… وقــام رجــال األمــن املتواجديــن يف املستشــفى بالقبــض عليــه‬\n      ‫وحتويلــه إلــى البحــث وتــويف املجنــي عليــه الحقـ ًا يف املستشــفى‪ .‬وبضبــط‬\n      ‫إفــادة املواطــن‪(........... /‬مرافــق املتهــم) أفــاد أنــه كان مرافــق الســائق‬\n      ‫‪...........‬وكان يجلــس باملرتبــة اخللفيــة وكانــوا قادمــن مــن الشــمال‬\n      ‫بإجتــاه اجلنــوب بعكــس اإلجتــاه أي املســار األيســر وخــرج املدعــوس مــن‬\n\n\n‫‪159‬‬\n\f‫بــن املتفرجــن يف وســط الســاحة وتعــرض للدعــس واســتقرت الســيارة‬\n‫باملنطقــة الصحراويــة وقامــوا بإســعاف املصــاب إلــى مستشــفى األميــر‬\n‫………‪ .‬وبضبــط إفــادة املواطــن‪(........... /‬مرافــق املتهــم) أفــاد أنــه‬\n‫مرافــق مــع الســائق ‪...........‬وكان راكــب باملرتبــة األماميــة وكانــوا‬\n‫يســيرون بســرعة ‪ 120- 100‬كــم وميــارس الســائق عمليــة التفحيــط‬\n‫وأثنــاء مــا كانــت الســيارة تزحــف علــى جانبهــا األيســر خــرج املدعــوس‬\n‫ووقــف يف منتصــف الطريــق (الســاحة) وكان يعــزز (يشــجع) املفحطــن‬\n‫وأثنــاء زحــف الســيارة أصدمــت بــه وســقط علــى األرض وقمنــا‬\n‫بإســعافه إلــى مستشــفى األميــر ………‪ .‬وقــد أثبــت التقريــر الطبــي‬\n‫رقــم (‪ )...........‬وتاريــخ ‪1433/11/13‬ه ـ الصــادر مــن مستشــفى األميــر‬\n‫عبدالعزيــز بــن مســاعد بحــق املواطــن‪...................... /‬بأنــه أحضــر الــى‬\n‫قســم اإلســعاف والطــوارئ بعــد تعرضــه حلــادث ســير بواســطة الشــرطة‬\n‫وكان بــه إصابــات متعــددة نــزف مــن األنــف والفــم وكان ال يتنفــس‬\n‫وال يســتجيب وال يوجــد نبــض ‪ ،‬ومت عمــل إنعــاش قلبــي رئــوي ملــدة‬\n‫‪ 35‬دقيقــة ولــم يســتجيب وتأكــدت الوفــاة الســاعة (‪ )03:30‬صباح ـ ًا‬\n‫‪ .‬كمــا أثبــت التقريــر الطبــي رقــم (‪...........‬وتاريــخ ‪1433/11/28‬ه ـ‬\n‫الصــادر مــن مستشــفى األميــر ……… بحــق املواطن‪.........../‬بأنــه‬\n‫أحضــر الــى قســم اإلســعاف والطــوارئ بتاريــخ ‪1433/11/5‬ه ـ بواســطة‬\n‫الشــرطة إثــر تعرضــه حلــادث ســير وكان يعانــي مــن أذى متعــدد ونــزف‬\n‫مــن األنــف والفــم وكان غيــر مســتجيب واليوجــد نبــض وال يتنفــس‬\n‫مت عمــل إنعــاش قلبــي رئــوي ملــدة ‪ 35‬دقيقــة ولــم يســتجيب وتأكــدت‬\n‫الوفــاة الســاعة(‪ )3:30‬صباح ـ ًا ‪ ،‬الســبب املباشــر للوفــاة ‪ :‬حــادث ســير‬\n‫وأذى متعــدد ‪ ،‬الســبب غيــر املباشــر للوفــاة ‪ :‬توقــف القلــب والتنفــس ‪.‬‬\n\n\n                                                                                      ‫‪160‬‬\n\f      ‫وقــد أثبــت التقريــر رقــم (‪ )...........‬الصــادر مــن شــعبة احلــوادث بــاإلدارة‬\n      ‫العامــة للمــرور مبنطقــة احلــدود الشــمالية أنــه ‪ :‬مبعاينــة مــكان احلــادث‬\n      ‫والوقــوف عليــه وتتبــع اآلثــار والتحقيــق فيــه اتضــح أن الســيارة كانــت‬\n      ‫تســلك الطريــق الغربــي للجامعــة بعكــس االجتــاه وخــرج املدعــوس مــن‬\n      ‫الشــرق إلــى الســاحة ووقــع الدعــس يف منتصــف الطريــق ويوجــد أثــر‬\n      ‫دمــاء باملنتصــف وتبعــد عــن رأس اإلزفلــت الشــرقي مســافة ‪ 37‬متــر‬\n      ‫وعــن رأس اجلزيــرة الغربــي مســافة ‪44‬متــر ‪ .‬حالــة اجلــو والطريــق ‪ :‬اجلــو‬\n      ‫كان صحــو ًا والرؤيــة واضحــة والطريــق صالــح للســير والوقــت (ليــا)‬\n      ‫نتــج عــن احلــادث مــا يلــي ‪ 1 :‬وفــاة املدعــوس وصــدر بحقــه التقريــر‬\n      ‫الطبــي املرفــق رقــم ‪...........‬وتأريــخ ‪1433/11/13‬ه ـ وشــهادة الوفــاة‬\n      ‫رقــم ‪...........‬يف ‪1433/11/14‬ه ـ اإلجــراءات املتخــذة باحلــادث ‪ , 1 :‬مت‬\n      ‫إدخــال جثمــان املتوفــى بثالجــة مستشــفى ســمو األميــر ………‪2 .‬‬\n      ‫جــرى تفتيــش الســيارة مبوقــع احلــادث ولــم يعثــر بهــا علــى أي شــي مــن‬\n      ‫احملرمــات أو املمنــوع شــرع ًا أو نظامـ ًا ‪ 3 .‬مت إيقــاف الســائق لدينــا رهــن‬\n      ‫إجــراءات احلــادث ‪ 4 .‬مت إبــاغ مرجــع الســائق بكتابنــا رقــم ‪...........‬‬\n      ‫يف ‪1433/11/5‬ه ـ ‪ 5‬مت صــدور قــرار هيئــة جــزاءات رقــم (‪ )...........‬يف‬\n      ‫‪1433/11/4‬ه ـ املتضمــن إيقــاف الســائق ملــدة ‪ 5‬أيــام وحجــز ســيارته‬\n      ‫ملــدة خمســة عشــر يومـ ًا ‪ . 6‬مت حجــز الســيارة مبركــز حجــز الســيارات‬\n      ‫‪ 7 .‬مت تســليم جثمــان املتوفــى لذويــه كمــا يتضــح مــن الصفحــة رقــم‬\n      ‫(‪ )6‬مــن محضــر التحقيــق املرفــق ‪ 8 .‬مت بعثــه لشــرطة ‪...........‬بنــاء علــى‬\n      ‫توجيه ســعادة مدير الشــرطة الشــفوي لنا ‪ .‬الرأي واملســئولية ‪ :‬مما تقدم‬\n      ‫ذكــره ومــن معاينــة املــكان والوقــوف عليــه وتتبــع اآلثــار والتحقيــق فيــه‬\n      ‫يتضــح اآلتــي ‪ :‬أو ًال ‪ /‬يــدان الســائق ‪........... /‬بنســبة وقدرهــا ‪ % 50‬جتــاه‬\n\n\n‫‪161‬‬\n\f‫احلــادث لألســباب التاليــة ‪-1 :‬ممارســته عمليــة التفحيــط حســب اآلثــار‬\n‫وباعترافــه ‪-2 .‬ماجــاء بشــهادة زمالئــه بــأن الســائق كان ميــارس عمليــة‬\n‫التفحيــط يف ســاحة اجلامعــة ‪ .‬ثاني ـ ًا ‪ /‬أمــا النســبة املتبقيــة وقدرهــا ‪50‬‬\n‫‪ %‬فتقــع علــى املدعــوس ‪........... /‬لألســباب التاليــة ‪-1 :‬كــون نقطــة‬\n‫الدعــس يف منتصــف الســاحة وتبعــد عــن مــكان املتجمهريــن مبســافة‬\n‫ال تقــل عــن ‪20‬متــر ‪-2 .‬ماجــاء بشــهادة الشــهود مــن أن ‪...........‬كان‬\n‫يشــجع املفحطــن علــى ممارســتهم التفحيــط ‪ -3 .‬عــدم وجــود مبــرر‬\n‫لتواجــده يف ســاحة تفحيــط يف الســاعة الثانيــة فجــر ًا يف منطقــة نائيــة‬\n‫ال يوجــد بهــا إنــارة والســيما أنــه رجــل أمــن مــدرك لعواقــب مــا قــام بــه‬\n‫‪ .‬املــواد النظاميــة ‪-:‬أو ًال ‪ /‬حتديــد املســئولية ‪-1-:‬تنطبــق املــادة ‪60‬مــن‬\n‫نظــام املــرور علــى الســائق ‪........... /‬والتــي نصهــا (يعــد احلــادث موجب ـ ًا‬\n‫للمســئولية إذا نتــج مــن اإلهمــال ‪ ،‬أو قلــة االحتــراز ‪ ،‬أو عــدم مراعــاة‬\n‫األنظمــة) ‪ .‬ثانيـ ًا ‪ /‬العقوبــات ‪-1 :‬تنطبــق املــادة (‪ )62‬مــن نظــام املــرور‬\n‫علــى الســائق ‪........... /‬والتــي نصهــا (كل مــن أتلــف نفــس إنســان ‪-‬‬\n‫ال أو بعضــا ‪ ،‬يف حــادث ســير متعديـ ًا ‪ ،‬أو مفرطـ ًا يعاقــب بالســجن‬       ‫ك ً‬\n‫مــدة ال تزيــد عــن ســنة واحــدة ‪ ،‬وبغرامــة ماليــه ال تزيــد عــن عشــرة‬\n‫آالف ريــال ‪ ،‬أو بإحــدى هاتــن العقوبتــن ‪ ،‬دون إخــال مبــا تقــرر‬\n‫للحــق اخلــاص) ‪ .‬ثالث ـ ًا ‪ /‬املخالفــات ‪-1 :‬تنطبــق املــادة (‪ )68‬مــن نظــام‬\n‫املــرور علــى الســائق ‪........... /‬والتــي نصهــا (مــع عــدم اإلخــال بــأي‬\n‫عقوبــة أشــد منصــوص عليهــا يف نظــام آخــر يعاقــب كل مــن يرتكــب‬\n‫إحــدى املخالفــات الــواردة يف جــداول املخالفــات امللحقــة بهــذا النظــام) ‪.‬‬\n‫وقــد أثبــت التقريــر الصــادر مــن هيئــة اجلــزاءات بــاإلدارة العامــة للمــرور‬\n‫مبنطقــة احلــدود الشــمالية أنــه اســتنادا علــى نظــام املــرور الصــادر‬\n\n\n                                                                                       ‫‪162‬‬\n\f      ‫باملرســوم امللكــي رقــم (م‪ )85/‬وتاريــخ ‪1428/10/26‬ه ـ وبنــاء علــى‬\n      ‫املــادة (‪ )1/67‬مــن الالئحــة التنفيذيــة لنظــام املــرور الصــادر بالقــرار‬\n      ‫الــوزاري رقــم (‪ )7019‬وتاريــخ ‪1429/7/3‬ه ـ بتشــكيل هيئــة للفصــل يف‬\n      ‫املنازعــات والقضايــا املروريــة واملشــكلة مبوجــب املــادة (‪ )1/1/67‬مــن‬\n      ‫الالئحــة التنفيذيــة لنظــام املــرور انعقــدت مبقــر إدارة مــرور عرعــر هيئــة‬\n                         ‫الفصــل يف املنازعــات والقضايــا املروريــة املشــكلة مــن ‪:‬‬\n                               ‫‪-‬رئيس الهيئة ‪/‬عقيد‪ .........../‬العضو‪ /‬رائد‪.........../‬‬\n      ‫‪-‬العضــو ‪ /‬نقيــب ‪ ........... /‬وذلــك للنظــر يف قضية ‪........... /‬رقم الســجل‬\n                                             ‫(‪ )...........‬وأصــدرت الهيئــة القرار التالي ‪-:‬‬\n      ‫‪-1‬إيقــاف الســائق ملــدة خمســة أيــام ‪-2 .‬حجــز املركبــة ملــدة خمســة‬\n                                           ‫عشــر يوم ـ ًا ‪-3 .‬غرامــة ماليــة ‪ 1000‬ريــال ‪.‬‬\n      ‫وقــد انتهــى التحقيــق إلــى اتهــام ‪ ،........... /‬بقتــل ‪...........‬شــبه عمــد‬\n      ‫وذلــك بصدمــه بســيارته والتســبب يف وفاتــه أثنــاء التفحيــط واالســتهتار‬\n      ‫وعــدم املبــاالة بتعريــض حيــاة اآلخريــن للخطــر ممــا أدى إلــى إزهــاق‬\n                                                                        ‫نفــس معصومــة ‪.‬‬\n      ‫وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف إقــرار املتهــم املصــدق‬\n      ‫شــرع ًا املدون على لفة (‪ )7‬صفحة رقم (‪ -2 . )1‬ما جاء يف أقوال املتهم‬\n      ‫املدونــة علــى لفــة (‪ -3 .)6-5-4‬مــا جــاء يف التقريــر الصــادر مــن اإلدارة‬\n      ‫العامة للمرور رقم (‪ )4052‬املرفق لفة(‪ -4)71-70-69‬ما جاء يف أقوال‬\n      ‫الشــهود املرافقــن للمتهــم املدونــة علــى لفــة (‪ )1‬صفحــة رقــم (‪-10-9-8‬‬\n      ‫‪ -5 . )11‬مــا جــاء يف التقاريــر الطبيــة املرفقــة لفــة (‪ . )74-73‬وحيــث أن‬\n      ‫ا محــرم‬   ‫مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعـ ً‬\n      ‫ومعاقــب عليــه شــرع ًا وذلــك بإزهاقــه نفــس معصومــة واســتناد ًا إلــى‬\n\n\n‫‪163‬‬\n\f‫تعميــم صاحــب الســمو امللكــي وزيــر الداخليــة رقــم (‪ )109043‬وتاريــخ‬\n‫‪1433/9/25‬ه ـ ‪ ،‬لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا‬\n‫قضــت بــه اإلرادة امللكيــة رقــم (‪ )2104/4/8‬وتاريــخ ‪1363/10/26‬ه ـ‬\n‫وتشــديد العقوبــة عليــه ‪( .‬علمـ ًا بــأن احلــق اخلــاص انتهــى بالتنــازل) وبــاهلل‬\n‫ا‬‫التوفيــق ‪ ،‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n‫مــا جــاء يف دعــوى املدعــي العــام ضــدي فكلــه صحيــح فقــد كنــت‬\n‫يــوم اخلميــس املوافــق ‪1433/11/4‬ه ـ الســاعة التاســعة مســاء كان مــع‬\n‫مجموعــة أشــخاص ومنهــم املجنــي عليــه ‪ ،........... /‬يف شــارع ‪...........‬‬\n‫نشــاهد مســيرات االحتفــال باليــوم الوطنــي ثــم ذهبنــا إلــى حــي ‪...........‬‬\n‫وتوقفنــا عنــد فنــادق ‪...........‬ثــم جــاءت رســالة علــى جوالــي عــن طريــق‬\n‫برنامــج البــاك بيــري وكان نصهــا (توجيــه تفحيــط بســاحة اجلامعــة‬\n‫‪ .....‬الــخ) ثــم ذهبنــا إلــى ســاحة اجلامعــة بســيارتي مــن نــوع جمــس حــوض‬\n‫لونهــا بنــي رقــم اللوحــة ‪ )...........‬غمــاره ونــص موديــل (‪ )2007‬وكان‬\n‫معــي بالســيارة شــخص يدعــى ‪...........‬وشــخص اســمه ‪...........‬و‪...........‬‬\n‫وذهبنــا إلــى ســاحة اجلامعــة ونــزل األشــخاص الذيــن كانــوا معــي‬\n‫بالســاحة ملشــاهدة التفحيــط وعندمــا انتهــى التفحيــط ركــب معــي‬\n  ‫‪...........‬و‪...........‬وذهبنــا نريــد الرجــوع إلــى عرعــر ولكــن إبليــس ســولَ‬\n‫لــي العــودة إلــى ســاحة التفحيــط ملمارســة التفحيــط وعندمــا كنــت‬\n‫افحــط بالســيارة كنــت اســير بســرعة (‪100‬كــم ‪ /‬الســاعة) وكان‬\n‫املجنــي عليــه ‪........... /‬واقفـ ًا بوســط الســاحة وكانــت الســاحة مظلمــة‬\n‫ولــم امتكــن مــن رؤيتــه إال عندمــا اقتربــت منــه فحاولــت االبتعــاد عنــه‬\n‫ولكــن لــم امتكــن مــن الســيطرة علــى الســيارة وحــاول املجنــي عليــه‬\n‫الهــروب مــن أمــام الســيارة ولــم يســتطع فصدمتــه فســقط علــى األرض‬\n\n\n                                                                                         ‫‪164‬‬\n\f      ‫علــى بعــد مســافة مــن الســيارة فتوقفــت ونزلــت مــن الســيارة وقامــت‬\n      ‫بإســعاف املجنــي عليــه إلــى مستشــفى األميــر ……… وقــام رجال األمن‬\n      ‫املتواجديــن يف املستشــفى بالقبــض علـ ّـي وحتويلــي إلــى البحــث وتــويف‬\n      ‫ـاء وقــدر‬\n               ‫املجنــي عليــه الحقـ ًا يف املستشــفى‪ . .‬إال أن مــا وقــع كان قضـ ً‬\n      ‫ولــم يكــن بــأي قصــد جنائــي منــي هكــذا أجــاب وبســؤاله هــل يوجــد‬\n      ‫عليــك أي ســوابق أجــاب بالنفــي ‪ .‬وبســؤال الطرفــن هــل لديكمــا مزيــد‬\n      ‫مرافعــة فأجابــا بأننــا نكتفــي مبــا مت ضبطــه ‪ .‬فجــرى منــي الرجــوع إلى‬\n      ‫إقــرار املدعــى عليــه املصــدق شــرع ًا املــدون الصفحــة رقــم (‪ )1‬مــن اللفــة‬\n      ‫رقــم (‪ )7‬فــإذا هــو كمــا ذكــر ‪ ،‬كمــا جــرى منــي الرجــوع إلــى أقوالــه‬\n      ‫املدونــة علــى لفــة رقــم (‪4‬ـ‪5‬ـ‪ ، )6‬وكذلــك التقريــر الصــادر مــن اإلدارة‬\n      ‫العامــة للمــرور املــدون علــى لفــة (‪69‬ـ‪70‬ـ‪ ، )71‬وكذلــك أقــوال الشــهود‬\n      ‫املدونــة علــى الصفحــة رقــم (‪8‬ـ‪9‬ـ‪10‬ـ‪ )11‬لفــة رقــم (‪ ، )1‬وكذلــك مــا‬\n      ‫جــاء يف التقاريــر الطبيــة املدونــة علــى لفــة رقــم (‪73‬ـ‪ )74‬فــإذا هــي كمــا‬\n      ‫ذكــر ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى وإجابــة املدعــى عليــه بصحــة‬\n      ‫مــا جــاء فيهــا حســب إجابتــه املرصــودة بعاليــة ولكونــه لــم يظهــر مــن‬\n      ‫معطيــات احلــادث وال مــن التحقيقــات وال مــن اعتــراف املدعــى عليــه‬\n      ‫وال مــن أدلــة املدعــي العــام مــا يشــير إلــى وجــود القصــد اجلنائــي ‪ ،‬وملــا‬\n      ‫جــاء يف التقريــر الصــادرة مــن اإلدارة العامــة للمــرور وكذلــك التقريــر‬\n      ‫الطبــي ولعــدم وجــود ســوابق مســجلة بحــق املدعــى عليــه وملــا جــاء يف‬\n      ‫املــادة (‪ )159‬مــن نظــام اإلجــراءات املتضمنــة أن للمحكمــة تغييــر‬\n      ‫الوصــف اجلرمــي ونظــر ًا النتشــار التفحيــط يف املجتمــع مــع مــا يحتــوي‬\n      ‫عليــه مــن خطــورة بالغــة ذهــب نتيجــة لهــا أرواح الكثيــر مــن األبريــاء‬\n      ‫إضافــة إلــى مــا يحتــوي عليــه مــن مقاصــد ومــآرب ال تخفــى علــى كل‬\n\n\n‫‪165‬‬\n\f‫مطلــع ‪ ،‬ولتنــازل أصحــاب احلــق اخلــاص وجلميــع مــا تقــدم فلــم يثبــت‬\n‫لــدي إدانــة املدعــى عليــه بالقتــل شــبه العمــد ولكــن ثبــت لــدي إدانتــه‬\n‫بالتفحيــط ممــا تســبب معــه بالقتــل اخلطــأ وحكمــت عليــه لقــاء ذلــك‬\n‫بالســجن ثــاث ســنوات مــن تاريــخ إيقافــه وجلــده مائــة وخمســن جلــده‬\n‫مفرقــة علــى خمــس دفعــات يف كل دفعــة ثالثــن جلــده يفصــل بــن كل‬\n‫إيقــاع والــذي يليــه بعشــرة أيــام ‪ .‬هــذا مــا حكمــت بــه وبعــرض احلكــم‬\n‫علــى املدعــى عليــه قــرر قناعتــه ورضــاه بــه‪ ،‬وأمــا املدعــي العــام فقــرر‬\n‫عــدم القناعــة واســتعد بتقــدمي الئحــة اعتراضيــة فتــم تســليمه نســخة‬\n‫مــن احلكــم وأفهــم بتعليمــات التمييــز وصلــى اهلل علــى نبينــا محمــد ‪.‬‬\n‫حــرر يف ‪1434/04/13‬ه ـ احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن‬\n‫قـض ــاة الدائ ــرة األولــى لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫مبنطقــة اجلــوف علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بعرعــر برقــم ‪ 34584651‬وتاريــخ ‪1434/4/28‬ه ـ املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪........... /‬‬\n‫املســجل برقــم ‪ 34186165‬وتاريــخ ‪1434/4/13‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ضــد‪........... /‬التهامــه بالقتــل والتســبب يف وفــاة شــخص‬\n‫اثنــاء التفحيــط وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة فقــد قررنــا باألكثريــة املصادقــة علــى احلكــم‪ .‬واهلل‬\n          ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪166‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":155,"source_page_end":166,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"933531d9785a2a2b2440964b54494b2f4b29826ec4d94985dcbfe710167d84d7","normalized_text_hash":"25969b11f0030ce3bcce2bc284309f035a7a7980f31651837948100339a862e4","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p155-34186165"},{"id":"357f8159-7dfa-587d-8466-0092396811df","document_type":"judgment","category":"judicial","subcategory":"general","title":"-1األمر السامي رقم 10711يف 1393/5/2ه وقرار مجلس القضاء األعلى بهيئته الدائمة برقم 3/51يف 1409/3/6ه املؤيد باألمر السامي رقم /1197/4م يف 1409/6/2ه املبلغ بالتعميم /8ت 95/يف 1409/7/25ه بشأن تطبيق اإلرادة امللكية على قاتل العمد وشبه العمد إذا تنازل أولياء الدم عن القصاص (التصنيف املوضوعي","document_number":"34177095","case_number":"34130796","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"-1األمر السامي رقم 10711يف 1393/5/2ه وقرار مجلس القضاء األعلى بهيئته الدائمة برقم 3/51يف 1409/3/6ه املؤيد باألمر السامي رقم /1197/4م يف 1409/6/2ه املبلغ بالتعميم /8ت 95/يف 1409/7/25ه بشأن تطبيق اإلرادة امللكية على قاتل العمد وشبه العمد إذا تنازل أولياء الدم عن القصاص (التصنيف املوضوعي","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34177095 :‬تاريخه‪1434/4/2 :‬هـ‬\n                         ‫رقم الدعوى‪34130796:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34231523‬تاريخه‪1434/6/5 :‬هـ‬\n\n\n      ‫طلــب إثبــات صفــة القتــل العمــد ‪ ،‬إرادة ملكيــة‪ ،‬قتــل مبثقــل ‪ ،‬اآللــة‬\n      ‫املســتخدمة يف اجلنايــة قرينــة محــددة للقصــد يعمــل بهــا مــا لــم‬\n      ‫يعارضــه مــا هــو أقــوى منــه ‪ ،‬إقــرار ‪ ،‬تنــازل عــن حــق خــاص ‪ ،‬تقريــر أدلــة‬\n      ‫جنائيــة ‪ ،‬صــرف النظــر عــن اإلدانــة بالقتــل العمــد‪ ،‬إدانــة بالقتــل شــبه‬\n                                                              ‫العمــد ‪ ،‬تعزيــر ‪ ،‬ســجن‪.‬‬\n\n\n\n      ‫‪ -1‬األمــر الســامي رقــم ‪ 10711‬يف ‪1393/5/2‬ه ـ وقــرار مجلــس القضــاء‬\n      ‫األعلــى بهيئتــه الدائمــة برقــم‪ 3/51‬يف ‪1409/3/6‬ه ـ املؤيــد باألمــر‬\n      ‫الســامي رقــم ‪/1197/4‬م يف ‪1409/6/2‬ه ـ املبلــغ بالتعميــم ‪/8‬ت‪ 95/‬يف‬\n      ‫‪1409/7/25‬ه ـ بشــأن تطبيــق اإلرادة امللكيــة علــى قاتــل العمــد وشــبه‬\n      ‫العمــد إذا تنــازل أوليــاء الــدم عــن القصــاص (التصنيــف املوضوعــي‬\n                                                 ‫لتعاميــم وزارة العــدل ‪.)782/1‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن االدعــاء العــام علــى املدعــى عليــه بقيامــه بقتــل‬\n      ‫شــقيقه عمــدا وعدوانــا وطلــب إثبــات صفــة القتــل واحلكــم عليــه وفــق‬\n      ‫مقتضــى اإلرادة امللكيــة حيــث تلقــت الشــرطة بالغــا بإصابــة املجنــي‬\n      ‫عليــه إصابــة بليغــة أدت لوفاتــه وباســتجواب أحــد أشــقائه أفــاد بــأن‬\n\n‫‪167‬‬\n\f‫اجلانــي املدعــى عليــه وأنــه ضربــه بطــوب علــى رأســه علــى إثــر شــجار ‪،‬‬\n‫انتهــى احلــق اخلــاص بالتنــازل ‪ ،‬أنكــر املدعــى عليــه التهمــة ودفــع بــأن‬\n‫الصحيــح حصــول مشــكلة بينــه وبــن أخيــه فغضــب فتنــاول كســرة‬\n‫مــن طــوب خرســاني فصــك بهــا رأســه وتــويف بعــد ذلــك ويبــدو بأنــه تــويف‬\n‫بســببها ‪ ،‬عليــه فإنــه لــم يقصــد قتلــه ألن احلجــر لــم يكــن كبيــرا ‪،‬‬\n‫جــرى االطــاع علــى التقريــر الطبــي املتضمــن بــأن وفــاة املجنــي عليــه‬\n‫بســبب إصابتــه إصابــة رضيــة ناشــئة عــن رشــقه بجســم صلــب راض‬\n‫«بلكــة خراســانية» أحدثــت نزيفــا شــديدا ضاغطــا علــى املــخ ‪ ،‬جــرى‬\n‫االطــاع علــى التقريــر املصــور مــن قبــل األدلــة اجلنائيــة واالطــاع علــى‬\n‫الصــورة امللتقطــة للحجــر املســتعمل يف اجلرميــة ‪ ،‬جــرى االطــاع علــى‬\n‫الصــك املثبــت تنــازل ورثــة املجنــي عليــه عــن املدعــى عليــه ‪ ،‬عليــه وألن‬\n‫املدعــى عليــه أقــر بضربــه املدعــى عليــه باحلجــر عمــدا إال أنــه أنكــر‬\n‫قصــد قتلــه ‪ ،‬عليــه وملــا قــرره الفقهــاء مــن أن اآللــة املســتخدمة يف اجلنايــة‬\n‫هــي احملــددة للقصــد ‪ ،‬عليــه وألن اآللــة املســتخدمة ال تقتــل غالبــا ‪،‬‬\n‫لــذا وبنــاء علــى مــا تضمنــه التقريــر الطبــي الشــرعي ‪ ،‬وبنــاء علــى مــا‬\n‫تضمنتــه اإلرادة امللكيــة ‪ ،‬وملجمــوع مــا تقــدم فقــد قــررت احملكمــة مــا‬\n‫يلــي‪ :‬أوال‪ /‬عــدم ثبــوت إدانــة املدعــى عليــه بقتــل شــقيقه عمــدا وعدوانــا‬\n‫وصرفــت النظــر عــن دعــوى املدعــي العــام‪ .‬ثانيــا‪ /‬ثبــوت قتــل املدعــى‬\n‫عليــه لشــقيقه شــبه عمــد ويطبــق يف حقــه مقتضــى اإلرادة امللكيــة‬\n‫بشــأنه بســجنه ســنتني ونصــف ‪ ،‬قــرر املدعــى عليــه القناعــة بينمــا‬\n‫اعتــرض املدعــي العــام فجــرى إفهامــه بالتعليمــات ‪ ،‬صــدق احلكــم مــن‬\n                                                           ‫محكمــة االســتئناف‪.‬‬\n\n\n\n                                                                                         ‫‪168‬‬\n\f      ‫احلمــد هلل وبعــد يف هــذا اليــوم الســبت املوافــق ‪ 1434/3/28‬ه ـ الســاعة‬\n      ‫العاشــرة صباحـ ًا لــدي أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة بالطائــف‬\n      ‫وبناء على املعاملة املقيدة برقم ‪ 34692239‬يف ‪1434/3/18‬هـ واحملالة‬                ‫ً‬\n      ‫إلينا برقم ‪ 34130796‬يف ‪ 1434/3/18‬هـ افتتحت اجللسة وفيها حضر‬\n      ‫املدعــى العام‪........../‬بالتعميــد رقم‪..........‬يف‪1433/3/12‬هـ ـ وادعــى‬\n      ‫علــى احلاضــر باملجلــس الشــرعي‪.......... /‬ســعودي اجلنســية مبوجــب‬\n      ‫ا ‪ :‬إنــه بتاريــخ ‪1432/10/4‬ه ـ ـ تبلــغ‬  ‫الســجل املدنــي رقــم ( ‪ )..........‬قائـ ً‬\n      ‫مخفــر شــرطة ‪..........‬مــن مستشــفى ‪..........‬العــام عــن وصــول املجنــي‬\n      ‫عليــه‪ ،.......... /‬ســعودي اجلنســية يبلــغ مــن العمــر ‪ )33( ،‬عــام وبــه إصابــة‬\n      ‫برأســه مــن اجلهــة اليســرى وتســببت لــه يف غيبوبــة تامه وحــول على أثرها‬\n      ‫ملستشــفى امللــك فيصــل مبحافظــة الطائــف وبســؤال املواطــن ‪........../‬‬\n      ‫شــقيق املجنــي عليــه الــذي كان يرافقــه عــن مــا حــدث للمجنــي عليــه‬\n      ‫أفــاد أن اإلصابــة التــي حلقــت باملجنــي عليــه نتيجة قيام شــقيقهم األكبر‬\n      ‫املدعــى عليــه بحذفــه بقطعــه مــن البلــك أثــر خــاف ومشــادة كالميــة‬\n      ‫بينهمــا بســبب مشــاجرة حدثــت بــن أبنائهمــا ويف متــام الســاعة السادســة‬\n      ‫مســاء يــوم اجلمعــة املوافــق ‪1433/10/6‬ه ـ ـ تبلغنــا مــن املديــر املنــاوب‬\n      ‫مبستشــفى امللــك فيصــل بالطائــف بــأن املجنــي عليــه‪.......... /‬أنتقــل إلــى‬\n      ‫رحمــه اهلل تعالــى وقــد فــارق احليــاة بســبب تلــك اإلصابــة ‪ ،‬وقــد انتهــى‬\n      ‫التحقيــق الــى توجيــه اتهــام للمدعــى عليــه بـ(قتــل شــقيقه‪.......... /‬عمــد ًا‬\n      ‫وعدوان ـ ًا وذلــك برميــه بحجــر (بلكــه خرســانيه )اصابتــه برأســه ممــا‬\n      ‫ادت إلــى وفاتــه ‪ ،‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل‬\n\n‫‪169‬‬\n\f‫أهليتــه املعتبــرة شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا اطلــب اثبــات‬\n‫صفــة القتــل العمــد والعــدوان واحلكــم عليــه وفــق مــا تقتضــي بــه اإلرادة‬\n‫امللكيــة يف حقــه والتــي تقضــي بســجنه والصــادرة باألمــر الســامي رقــم‬\n‫(‪ )2624‬يف ‪1372/4/9‬ه ـ ووفــق مــا ورد بقــرار مجلــس القضــاء األعلــى‬\n‫رقــم (‪ )3/106‬وتاريــخ ‪1408/4/23‬ه ـ املؤيــد باألمــر الســامي رقــم‬\n‫‪ 1197/4‬يف ‪1409/6/12‬ه ـ ‪( ،‬علم ـ ًا أن احلــق اخلــاص انتهــى بالتنــازل‬\n‫املصــدق شــرعاً) هــذه دعــواي ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n‫بقولــه‪ :‬مــا ذكــره املدعــي العــام يف دعــواه مــن اتهامــي بقتــل شــقيقي‬\n‫‪..........‬عمــد ًا وعدوانـ ًا فغيــر صحيــح ‪ ،‬والصحيــح أنــه حصلــت بينــه وبــن‬\n‫ابنــي مشــكلة فغضبــت منــه وقمــت بأخــذ كســرة بلكــة خراســانية‬\n‫ورميتــه بهــا فأصابــت رأســه ‪ ،‬ثــم تــويف بعــد ذلــك ويبــدو أن الوفــاة بســبب‬\n‫هــذه اإلصابــة ‪ ،‬وبالتالــي فإننــي لــم أقصــد قتلــه ألن احلجــر لــم يكــن‬\n‫ـاء علــى ذلــك فقــد رفعــت اجللســة‪ .‬ثــم يف يــوم‬\n                                                   ‫كبيــر ًا هكــذا أجــاب وبنـ ً‬\n‫الثالثــاء املوافــق ‪1434/4/2‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫العــام واملدعــى عليــه ‪ ،‬فبعــد ســماعي للدعــوى وإجابــة املدعــى عليــه‬\n‫بنفــي مــا جــاء فيهــا مــن قتلــه ألخيــه املجنــي عليــه عمــد ًا وعدوانـ ًا ‪ ،‬مــع‬\n‫ا ذلــك‬‫اقــراره بأنــه تعمــد رميــه باحلجــر املشــار اليــه يف الدعــوى ‪ ،‬معل ـ ً‬\n‫مبــا جــاء يف جوابــه ‪ ،‬وبعــد االطــاع علــى جميــع اوراق املعاملــة مبــا‬\n‫فيهــا إقــرار املدعــى عليــه املصــدق شــرعا لفــه ‪ 4‬ص ـ ‪ ، 9-10‬وشــهادة‬\n‫الوفــاة لفــه ‪ ، 40‬والتقريــر الطبــي الشــرعي لفــه ‪ 14-17‬املتضمــن (‬\n‫أن وفــاة املجنــي عليــه بســبب اصاباتــه الرضيــه بالــرأس والناشــئة مــن‬\n‫رشــقه بجســم صلــب راض « بلكــة خرســانية « مبــا احدثتــه مــن نزيــف‬\n‫شــديد ضاغــط علــى املــخ ) ‪ ،‬والتقريــر املصــور لألدلــة اجلنائيــة لفــه ‪-70‬‬\n\n\n                                                                                          ‫‪170‬‬\n\f      ‫‪ 44‬املتضمــن صــور فتوغرافيــة للحجــر املســتخدم يف اجلرميــة ‪ ،‬وصــورة‬\n      ‫الصــك الصــادر مــن احملكمــة العامــة ب‪..........‬املرفقــة باملعاملــة لفــه ‪94‬‬\n      ‫املتضمــن (تنــازل والــدي املقتــول عــن املطالبــة بالقصــاص والديــة وأي‬\n      ‫مقابــل مــادي لوجــه اهلل تعالــى) ‪ ،‬وألن املدعــى عليــه اقــر بأنــه تعمــد‬\n      ‫رمــي املجنــي عليــه باحلجــر املوصــوف بعاليــه ‪ ،‬وأنكــر انــه قصــد قتلــه‬\n      ‫‪ ،‬وملــا قــرره العلمــاء مــن أن اآللــة املســتخدمة هــي التــي حتــدد القصــد‬\n      ‫‪ ،‬وألن اآللــة املســتخدمة يف هــذه اجلرميــة ال تقتــل غالب ـ ًا ‪ ،‬وبنــاء علــى‬\n      ‫التقريــر الطبــي الشــرعي املشــار الــى مضمونــه بعاليــه ‪ ،‬وبنــاء علــى‬\n      ‫االرادة امللكيــة الصــادرة باألمــر الســامي رقــم ‪ 2624‬يف ‪1372/4/9‬ه ـ‬\n      ‫‪ ،‬لهــذا كلــه فقــد صــدر منــي مــا يلــي ‪ :‬أوالً‪ :‬لــم يثبــت لــدي قتــل املدعــى‬\n      ‫عليــه لشــقيقه ‪..........‬عمــد ًا عدوانـ َا وصرفــت النظــر عــن دعــوى املدعــي‬\n      ‫العــام يف ذلــك‪ .‬ثاني ـ َا ‪ :‬ثبــت لــدي أن قتــل املدعــى عليــه لشــقيقه مــن‬\n      ‫قبيــل شــبه العمــد وتنطبــق بحقــه اإلرادة امللكيــة املشــار اليهــا بعاليــه‬\n      ‫والتــي تقضــي بســجن قاتــل شــبه العمــد ســنتني ونصــف وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه قــرر القناعــة وأمــا املدعــى العــام فقــرر االعتــراض‬\n      ‫بالئحــة فجــرى إفهامــه بتعليمــات االســتئناف ‪ ،‬وصلــى اهلل وســلم علــى‬\n      ‫نبينــا محمــد‪ .‬حــرر يف ‪1434/04/02‬هــ‪ .‬احلمــد هلل وحــده وبعــد ففــي‬\n      ‫هــذا اليــوم األثنــن املوافــق ‪1434/6/19‬ه ـ افتتحــت اجللســة وقــد وردتنــا‬\n      ‫املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار الدائــرة اجلزائيــة‬\n      ‫الثانيــة رقــم (‪ )34235635‬يف ‪1434/6/10‬ه ـ املتضمــن املصادقــة علــى‬\n      ‫احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪ ،‬وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد‪ .‬حــرر يف ‪1434/6/19‬هــ‪ .‬احلمــد هلل والصــاة والســام علــى‬\n      ‫رســول اهلل وبعــد ‪ :‬ـ ـ نحــن رئيــس وقضــاة الدائــرة اجلزائيــة الرابعــة يف‬\n\n\n‫‪171‬‬\n\f‫محكمــة اإلســتئناف مبنطقــة مكــة املكرمــة جــرى منــا االطــاع علــى‬\n‫القــرار رقــم ‪ 34177095‬وتاريــخ ‪1434/4/2‬ه ـ الصــادر مــن فضيلــة‬\n‫الشــيخ‪........../‬القاضي باحملكمــة اجلزائيــة بالطائــف ‪ ،‬املتضمــن دعوى‬\n‫املدعــي العــام ضــد‪ ،.......... /‬املتهــم بقتــل شــقيقه ‪ ،‬احملكــوم فيــه مبــا‬\n‫دون باطنــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه تقــرر باالكثريــة املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪172‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":167,"source_page_end":172,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4df0d524ad1e2d81c777b037db81e5effee4b73725de5d37460b316eacec233c","normalized_text_hash":"42eecaeb09d4cfd9ae940c0d1fd1a3ee83ce2be3aca83d23acacc8109a7e0a50","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p167-34177095"},{"id":"0bffec80-ac07-5ca6-b2a2-c7f650b70a91","document_type":"judgment","category":"judicial","subcategory":"general","title":"دية -دية قتل نفس خطأ -العبرة يف حتديد قيمة الدية وقت احلكم ال وقت القتل .","document_number":"34215859","case_number":"34168839","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بصبيا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/19","year":"1434","subject":"دية -دية قتل نفس خطأ -العبرة يف حتديد قيمة الدية وقت احلكم ال وقت القتل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34215859 :‬تاريخه‪1434/5/19 :‬هـ‬\n                          ‫رقم الدعوى‪34168839:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34390555‬تاريخه‪1434/12/29 :‬هـ‬\n\n\n      ‫ديــة ‪ -‬ديــة قتــل نفــس خطــأ‪ -‬العبــرة يف حتديــد قيمــة الديــة وقــت‬\n                                                    ‫احلكــم ال وقــت القتــل ‪.‬‬\n\n\n\n\n                  ‫قرار الهيئة العامة باحملكمة العليا رقم ‪ 2‬يف ‪1431/7/14‬هـ‪.‬‬\n\n\n\n\n      ‫حضــر املدعــي وكال ـ ًة بوكاالتــه املســتوفية التصديقــات الرســمية‬\n      ‫وادعــى علــى املدعــى عليــه بأنــه حصــل حــادث دهــس ملــورث موكليــه‬\n      ‫وقــد توفــى علــى إثــره مبوجــب شــهادة الوفــاة وكانــت نســبة اخلطــأ علــى‬\n      ‫املتســبب يف احلــادث ومســئوليته عنهــا خمســة وعشــرين باملائــة وقــد قنــع‬\n      ‫مــوكاله بهــذه النســبة‪ ،‬وطلــب احلكــم علــى املدعــى عليــه بدفــع ربــع‬\n      ‫ديــة اخلطــأ‪ ،‬بعــرض الدعــوى علــى املدعــى عليــه صــادق عليهــا وعلــى‬\n      ‫نســبة اخلطــأ‪ ،‬وقــرر بأنــه دفــع مبلغ ـ ًا بشــيك قــدره خمســة وعشــرون‬\n      ‫ألــف ريــال لبيــت مــال احملكمــة وال مانــع لديــه مــن تســليمه للمدعــي‬\n      ‫وكالــة‪ ،‬جــرى االطــاع علــى القــرار الشــرعي الصــادر بشــأن إدانــة‬\n      ‫املدعــى عليــه بنســبة ‪ %25‬يف احلــادث املذكــور كمــا جــرى االطــاع‬\n      ‫علــى شــهادة الوفــاة ‪ ،‬وصــك حصــر الورثــة للمتوفــى املتضمــن انحصــار‬\n      ‫ورثتــه يف والديــه ‪،‬جــرى االطــاع علــى قــرار الهيئــة العامــة باحملكمــة‬\n\n‫‪183‬‬\n\f‫العليــا املتضمــن بــأن ديــة اخلطــأ ثالثمائــة الــف ريــال وأن هــذا التقديــر‬\n                 ‫يســري علــى كل حالــة لــم يحكــم فيهــا قبــل العمــل بــه‪.‬‬\n‫ثبــت أن ديــة املتوفــى املذكــور أعــاه قدرهــا خمســة وســبعون ألــف ريــال‬\n‫ســعودي مبقــدار نســبة اخلطــأ‪ ،‬ومت احلكــم مبــا يلــي‪ :‬أو ًال إلــزام املدعــى‬\n‫عليــه بدفــع مبلــغ قــدرة خمســة وســبعون الــف ريــال للمدعــي وكالــة‬\n‫ـدي املتوفــى املذكــور مــن ديتــه نصيــب األم الســدس وقــدره‬    ‫نصيــب والـ ّ‬\n‫اثنــا عشــر ألفــا وخمســمائة ريــال والباقــي لــأب وقــدره اثنــان وســتون‬\n‫ألف ـ ًا وخمســمائة ريــال ثاني ـ ًا إفهــام املدعــى عليــه بــأن عليــه كفــارة‬\n‫القتــل اخلطــأ وهــي عتــق رقبــة مؤمنــة فــإن لــم يجــد فصيــام شــهرين‬\n‫متتابعــن‪ ،‬بعــرض احلكــم علــى الطرفــن قــرر املدعــي وكالــة القناعــة‬\n‫وقــرر املدعــى عليــه عــدم القناعــة وطلــب رفــع املعاملــة إلــى محكمــة‬\n‫االســتئناف واســتعد بتقــدمي الئحــة اعتراضيــة فأجيــب لطلبــه وبعــد رفــع‬\n                          ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة العامــة بصبيــا‬\n‫وبنــاء علــى املعاملــة املقيــدة باحملكمــة برقــم ‪ 34109270‬احملالــة‬\n‫لنــا برقــم ‪ 34168839‬وتاريــخ ‪1434/4/13‬ه ـ اخلاصــة بدعــوى ‪...‬‬\n‫صومالــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬وكالــة ضــد ‪ ...‬يف‬\n‫حــادث مــروري يف احلــق اخلــاص ففــي يــوم األحــد املوافق‪1434/5/19‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة والنصــف صباح ـ ًا وفيهــا حضــر ‪...‬‬\n‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬املنتهيــة بتاريــخ ‪1435/1/20‬هـ‬\n‫الصــادرة مــن إدارة اجلــوازات بالدمــام الوكيــل الشــرعي عــن كل مــن ‪...‬‬\n\n                                                                                     ‫‪184‬‬\n\f      ‫صومالــي اجلنســية حامــل بطاقــة شــخصية رقــم ‪ ...‬الصــادرة مــن ســجالت‬\n      ‫أحــوال مقديشــو و ‪ ...‬صوماليــة اجلنســية حتمــل بطاقــة رقــم ‪ ...‬املقيمــة‬\n      ‫يف مقديشــو مبوجــب الوكالــة رقــم ‪ 8/325‬يف ‪2009/4/4‬م الصــادرة‬\n      ‫مــن احملكمــة اإلســامية مبحافظــة بنــادر جمهوريــة الصومــال املخــول‬\n      ‫لــه فيهــا املرافعــة واملدافعــة واملطالبــة واســتالم الديــة والتوقيــع املصــادق‬\n      ‫عليهــا مــن ســفارة اجلمهوريــة الصوماليــة بالريــاض قســم القنصليــة برقــم‬\n      ‫‪ 2009/0086‬يف ‪2009/7/8‬م ووزارة اخلارجيــة فــرع منطقــة مكــة‬\n      ‫املكرمــة بتاريــخ ‪1430/7/22‬ه ـ وفــرع وزارة العــدل مبنطقــة جــازان‬\n      ‫برقــم ‪ 274‬يف‪1430/7/25‬ه ـ املرفــق صورتهــا باملعاملــة وادعــى علــى‬\n      ‫احلاضــر معــه باملجلــس الشــرعي ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...‬يف ‪1409/1/29‬ه ـ الصــادرة من األحــوال املدنية بخميس‬\n      ‫ا يف حتريــر دعــواه إنــه بتاريــخ ‪1429/12/14‬ه ـ حصــل‬            ‫مشــيط قائ ـ ً‬\n      ‫حــادث دهــس ملــورث موكلـ ّـي ‪ ...‬صومالــي اجلنســية الديانــة مســلم وقــد‬\n      ‫توفــى علــى إثــره بتاريــخ ‪1429/12/15‬ه ـ وذلــك مبوجــب شــهادة الوفــاة‬\n      ‫رقم ‪ 518‬يف ‪1430/1/6‬هـ الصادرة من مكتب األحوال املدنية بصبيا‬\n      ‫وكان املتســبب يف وفاتــه هــذا املدعــى عليــه احلاضــر أمامكــم الــذي‬\n      ‫كان يقــود ســيارة مــن نــوع ‪ ...‬رقــم اللوحــة(‪ )...‬نتــج عــن هــذا احلــادث‬\n      ‫وفــاة مــورث موكلـ ّـي املذكــور وكانــت نســبة اخلطــأ علــى املتســبب‬\n      ‫يف احلــادث ومســئوليته عنهــا خمســة وعشــرون باملئــة ‪ %25‬وموكلـ ّـي‬\n      ‫مقتنعــان بهــذه النســبة وقــد انحصــر إرثــه يف والديــه وهمــا موكلـ ًّـي‬\n      ‫املذكــوران أعــاه وذلــك مبوجــب صــك حصــر الورثــة الرقــم بــدون‬\n      ‫وتاريــخ ‪1430/11/7‬ه ـ الصــادر مــن احملكمــة اإلســامية مبحافظــة‬\n      ‫بنــادر جمهوريــة الصومــال واملصــادق عليــه مــن قبــل ســفارة اجلمهوريــة‬\n\n\n‫‪185‬‬\n\f‫الصوماليــة قســم القنصليــة رقــم ‪ 09/96/00‬يف ‪1430/11/7‬ه ـ ووزارة‬\n‫اخلارجيــة بتاريــخ ‪1430/11/8‬ه ـ وفــرع وزارة العــدل بجــازان برقــم ‪597‬‬\n‫يف ‪1430/11/12‬ه ـ أطلــب احلكــم علــى املتســبب احلاضــر أمامكــم‬\n‫بدفــع ديتــه بقــدر نســبة اخلطــأ عليــه وهــي خمســة وعشــرون باملئــة‬\n‫‪ %25‬هــذه دعــواي وبســؤال املدعــى عليــه عمــا جــاء يف دعــوى املدعــي‬\n‫ا لقــد كنــت عائــد ًا مــن جــازان إلــى أبهــا وتفاجــأت‬ ‫وكالــة أجــاب قائـ ً‬\n‫يف مــكان مظلــم وغيــر مخصــص للمشــاة ال أعــرف مكانــه بالضبــط‬\n‫ا مــن ليلــة ‪1429/12/14‬ه ـ بعبــور أربعــة‬    ‫تقريبـ ًا يف الســاعة الواحــدة ليـ ً‬\n‫أشــخاص مجهولــي الهويــة حاولــت تفــادى احلــادث قــدر املســتطاع لكــن‬\n‫الســيارة حلقــت باألخيــر منهــم وهــو املتوفــى الــذي ذكــره املدعــي وكالة‬\n                             ‫احلاضــر أمامكــم وأصــادق علــى أن نســبة ّ‬\n‫اخلطــأ علـ َـي ومســئوليتي يف‬\n‫هــذا احلــادث هــي خمســة وعشــرون باملئــة ‪ %25‬وقــد دفعــت مبلغـ ًا وقــدرة‬\n‫خمســة وعشــرون الــف ريالـ ـ ـ ـ ــ‪ 25000‬أمنتــه يف بيــت مــال احملكمــة‬\n‫بالشــيك رقــم ‪ 262828‬يف ‪2009/1/25‬م املســحوب علــى مصــرف‬\n‫الراجحــي فــرع الرونــة وال مانــع عنــدي مــن تســليمه للمدعــي وكالــة‬\n‫احلاضــر أمامكــم هكــذا أجــاب بنــاء علــى مــا تقــدم وبعــد االطــاع على‬\n‫أوراق املعاملــة وبعــد االطــاع علــى صــك الوكالــة وعلــى صــك احلصــر‬\n‫املذكوريــن أعــاه وملطابقتهمــا علــى مــا عطــف عليهمــا وبعــد االطــاع‬\n‫علــى القــرار الشــرعي رقــم ‪ 4/107‬يف ‪1430/6/2‬ه ـ الصــادر مــن‬\n‫احملكمــة اجلزئيــة بخميــس مشــيط املتضمــن إثبــات إدانــة املدعــى عليــه‬\n‫بنســبة خمســة وعشــرين باملئــة ‪ %25‬يف احلــادث املذكــور وبعــد االطــاع‬\n‫علــى شــهادة الوفــاة املذكــورة أعــاه ومطابقتهــا ملــا عطــف عليهــا‬\n‫وحيــث صــادق املدعــي عليــه عمــا جــاء يف دعــوى املدعــي وكالــة جملــة‬\n\n\n                                                                                       ‫‪186‬‬\n\f      ‫ا وبعــد االطــاع علــى الشــيك املذكــور رقمــه وتاريخــه أعــاه‬         ‫وتفصي ـ ً‬\n      ‫وعلــى اإليصــال رقــم ‪ 2/588449‬يف ‪1430/2/23‬ه ـ الصــادر مــن بيــت‬\n      ‫مــال محكمــة صبيــا املتضمــن اســتالمهم ملبلــغ وقــدره خمســة وعشــرون‬\n      ‫الــف ّريالـ ـ ـ ــ‪ 25000‬لصالــح ورثــة ‪ ...‬صومالــي وبعــد االطــاع علــى قــرار‬\n      ‫الهيئــة العامــة باحملكمــة العليــا رقــم ‪ 2‬يف ‪1431/7/14‬ه ـ املتضمــن‬\n      ‫بــأن ديــة اخلطــأ ثالثمائــة الــف ريــال (‪ )300000‬وأن هــذا التقديــر يســري‬\n      ‫علــى كل حالــة لــم يحكــم فيهــا قبــل العمــل بــه لذلــك كلــه فقــد ثبــت‬\n      ‫لــدي أن ديــة املتوفــى املذكــور أعــاه قدرهــا خمســة وســبعون ألــف‬\n      ‫ريالـ ــ(‪ )75000‬ســعودي مبقــدار النســبة املقــررة أعــاه وحكمــت باآلتي‬\n      ‫أو ًال ألزمــت املدعــى عليــه ‪ ...‬بدفــع مبلــغ وقــدرة خمســة وســبعون الــف‬\n      ‫ـدي املتوفــى‬\n                 ‫ا وتســليمه للمدعــي وكالــة ‪ ...‬والـ ّ‬    ‫ريال ـ ـ ــ(‪ )75000‬كام ـ ً‬\n      ‫املذكــور مــن ديتــه ثانيـ ًا أفهمــت املدعــى عليــه بــأن عليــه كفــارة القتــل‬\n      ‫اخلطــأ وهــي عتــق رقبــة مؤمنــة فــإن لــم يجــد فصيــام شــهرين متتابعــن‬\n      ‫بذلــك حكمــت وألزمــت وبعرضــه عليهمــا قــرر املدعــي وكالــة القناعــة‬\n      ‫وقــرر املدعــى عليــه عــدم القناعــة وطلــب رفــع املعاملــة الــى محكمــة‬\n      ‫االســتئناف واســتعد بتقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وعلــى ذلــك‬\n      ‫جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد والــه‬\n      ‫وصحبــه وســلم حــرر يف ‪1434/5/19‬ه ـ ويف هــذا اليــوم االثنــن املوافــق‬\n      ‫‪1434/11/10‬ه ـ افتتحــت اجللســة يف متــام الســاعة الواحــدة والنصــف‬\n      ‫وفيهــا ‪ ...‬صومالــي اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ ...‬وقــد كان‬\n      ‫هنــاك موعــد بتاريــخ ‪1434/10/27‬ه ـ إال أنــه قــد تعطــل النظــام وجــرى‬\n      ‫حتديــد هــذا املوعــد ويف هــذا اليــوم جــرى منــا االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس محكمــة االســتئناف مبنطقــة عســير برقــم‬\n\n\n‫‪187‬‬\n\f‫‪ 341573037‬يف ‪1434/8/10‬هـ املرفق قرار املالحظة رقم ‪34266697‬‬\n‫يف ‪1434/7/12‬ه ـ ونصــه (احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن‬\n‫قضــاة الدائــرة الثانيــة لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n‫مبنطقــة عســير علــى املعاملــة الــواردة من فضيلة رئيــس احملكمة العامة‬\n‫بصبيا الشــيخ ‪ ... /‬برقم ‪ 34109270‬وتاريخ ‪1434/6/19‬هـ املرفق بها‬\n‫القــرار الصــادر مــن فضيلتــه برقــم ‪ 34215859‬وتاريــخ ‪1434/5/19‬ه ـ‬\n‫اخلــاص بدعــوى املدعــي ‪ ... /‬بالوكالــة (صومالــي اجلنســية ) ضــد ‪/‬‬\n‫‪( ...‬ســعودي اجلنســية ) يف قضيــة (مطالبــة بديــة متوفــى ) علــى الصفــة‬\n‫املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫فيــه وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة لوحــظ مــا يلــي ‪ :‬أو ًال ‪ /‬الوكالــة لــم تتضمــن أن للوكيــل حــق‬\n‫اإلقــرار واملرافعــات ‪ .‬ثانيـ ًا ‪ /‬لــم يصــادق علــى صحــة صورتــي الوكالــة‬\n‫وحصــر اإلرث مبطابقتهــا ألصلهــا ‪ .‬ثالث ـ ًا ‪ /‬لــم يقســم املبلــغ احملكــوم‬\n‫بــه علــى املدعــى عليــه بــن الورثــة ويوضــح نصيــب كل وارث ‪ .‬رابع ـ ًا ‪/‬‬\n‫يوجــد بعــض األخطــاء اللغويــة فتصحــح ‪ .‬فعلــى فضيلتــه مالحظــة ذلــك‬\n‫وإكمــال مــا يلــزم نحــوه ومــن ثــم تعــاد املعاملــة حملكمــة االســتئناف‬\n‫إلكمــال الزمهــا ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم قاضــي اســتئناف ‪ ...‬ختــم وتوقيــع قاضــي اســتئناف ‪...‬‬\n‫ختــم وتوقيــع رئيــس الدائــرة ‪ ...‬ختــم وتوقيــع انتهــى وأجيــب على أصحاب‬\n‫الفضيلــة ســلمهم اهلل تعالــى بــأن الوكيــل قــد أحضــر يف هــذه اجللســة‬\n‫الوكالــة رقــم ‪ 9/486‬يف ‪1434/11/2‬ه ـ املرفــق صورتهــا باملعاملــة‬\n‫الصــادرة مــن محكمــة ناحيــة بنــادر اجلمهوريــة الفدراليــة االنتقاليــة‬\n‫الصوماليــة املخــول لــه فيهــا باملرافعــة واملدافعــة وحضــور اجللســات‬\n\n\n                                                                                   ‫‪188‬‬\n\f      ‫واإلقــرار واإلنــكار وحلــف اليمــن وردهــا وقبــول احلكــم واالعتــراض‬\n      ‫عليــه وطلــب التمييــز واالســتالم والتســليم وإنهــاء كافــة اإلجــراءات‬\n      ‫الالزمــة واجلــواب علــى املالحظــة الثانيــة بأنــه قــد جــرت املصادقــة منــا‬\n      ‫علــى صــور الــوكاالت وحصــر اإلرث ومطابقتهــا ألصولهــا وأمــا اجلــواب‬\n      ‫علــى املالحظــة الثالثــة فقــد ســألت املدعــي وكالــة ‪ :‬هــل للمتوفــى إخــوة‬\n      ‫أجــاب نعــم لــه أختــان شــقيقتان أعمارهمــا أكثــر مــن عشــر ســنوات‬\n      ‫ـاء علــى صــك احلصــر فــإن نصيــب األم‬     ‫هكــذا أجــاب وعلــى ذلــك وبنـ ً‬\n      ‫الســدس وقــدره اثنــا عشــر ألفــا وخمســمائة ريــال (‪ )12500‬والباقــي‬\n      ‫لــأب وقــدره اثنــان وســتون ألفـ ًا وخمســمائة ريــال (‪ )62500‬وأمــا اجلواب‬\n      ‫علــى املالحظــة الرابــع فقــد جــرى تصحيــح األخطــاء اللغويــة وأمــرت‬\n      ‫بإحلــاق ذلــك بصكــه وســجله وبعثــه حملكمــة االســتئناف لتدقيقه وعلى‬\n      ‫ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n      ‫آلــه وصحبــه وســلم حــرر يف ‪1434/11/10‬ه ـ الســاعة الثانيــة ظهــر ًا‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بصبيــا الشــيخ ‪ ... /‬برقــم‬\n      ‫‪ 341573037‬وتاريــخ ‪1434/11/25‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلتــه برقــم ‪ 34215859‬وتاريــخ ‪1434/5/19‬هـ اخلاص بدعوى‬\n      ‫املدعــي ‪ ... /‬بالوكالــة ( صومالــي اجلنســية ) ضــد‪ ( ... /‬ســعودي‬\n      ‫اجلنســية ) يف قضيــة ( مطالبــة بديــة متوفــى ) علــى الصفــة املوضحــة يف‬\n      ‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث‬\n      ‫ســبق دراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n      ‫املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه وأحلقــه بالقــرار وصــورة‬\n\n\n‫‪189‬‬\n\f‫ـاء علــى قرارنــا رقــم ‪ 34266697‬وتاريــخ ‪1434/7/12‬هــ‪.‬‬           ‫ضبطــه بنـ ً‬\n‫تقــررت املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى‬\n                              ‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪190‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"45a888f7-4670-5000-b7a6-758fee43997d","source_page_start":183,"source_page_end":190,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"19e897c2173e3901521cfae529a3d1e6dd0f01087fa3fe59a0993c513bc185e1","normalized_text_hash":"25346c7756ee6304a321d81b75b0da2a23c8fe273266a057558bd4f934a732f8","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v13-p183-34215859"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
